INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('nature', 'daemon', 'daemon', 'Daemon', NULL, '{"nature":"daemon","description":"Un Daemon n’est pas une espèce mais une âme morte choisie par une ancienne Divinité, retirée du Cycle puis reforgée comme Élu et porte de sa puissance. Chaque incarnation ajoute une vraie vie à cette histoire antérieure. La Divinité marque l’âme en profondeur, la Fonction est un rôle appris dans sa Cour et la Maisonnée une culture de service ; les anciens dieux ne se réduisent pas à une incarnation abstraite du Mal malgré leur démonisation après la victoire d’Elynea.","carte":"**DAEMON · NATURE**\n\n- **Voilé** : incarnation mortelle sous l''Hologramme. Aucun pouvoir, sauf ceux marqués V.\n- **Semi-Révélé** : la Marque transparaît. Profil SR de ta Divinité. Vision des âmes, Faveur divine et talents SR.\n- **Révélé** : forme exaltée, à l''image de ton Dieu, de ton passé et de ta personnalité. Profil R de ta Divinité (il remplace le SR). Tous les talents R. Une description ne donne rien : des ailes décoratives ne volent pas. Si tu reviens vers une forme au maximum de PV plus bas, tes PV actuels sont plafonnés.\n\n**Traits gratuits**\n\n- **Âme élue** : ton âme a quitté le Cycle, elle est liée à ta Divinité. À la mort de l''incarnation, elle retourne à sa Cour : le personnage est fini.\n- **Vision des âmes** (SR/R, 1 PA sous pression) : tu vois la nature spirituelle d''une créature perçue (âme mortelle, Khinae, corruption, Mageius, marque divine…). Pour lire plus loin : Esprit + Perception contre Volonté + Force Mentale. Ni à travers les murs, ni en radar.\n- **Assimilation des prières** (SR/R) : dans un Lieu de Résonance de ta Divinité (un lieu durablement imprégné de ses valeurs ou de prières), *Faveur divine* : 1/scène, +3 à un test cohérent avec une de ses Facettes. Tu sens vaguement la direction d''un Lieu puissant proche.\n- **Jet de pouvoir** : Volonté + Maîtrise spirituelle + 1d10e, sauf mention. Un effet évitable affronte la Défense physique ; un effet imposé à l''âme, l''esprit ou l''organisme affronte la Défense occulte. Jamais les deux.\n\n**Faiblesse** : aucune malédiction de Nature. Une seule Divinité, une seule Faveur active. Tes pouvoirs sont des portes précises : un Daemon n''improvise pas.\n\n**Origine de l''Élu** : Éveillé ou Héros (aucun effet), Ancien Prophète (rare, accord du MJ, ouvre la Rémanence prophétique, voie Vies passées).\n\n### Précisions communes (référence)\n\n- Actions et Réactions : 1 PA sauf mention. Une zone : un seul jet, comparé à chaque cible.\n- Les bonus équivalents, propriétés identiques et réductions de même source ne se cumulent pas.\n- **Plafond de survie (nouveau)** : par scène, un Daemon ne profite que d''un seul effet qui lui évite la mort : Permission de mourir, Vies offertes, Dernier Rempart ou Refus du crépuscule reçu.\n- Tout ce qui se définit avec le MJ (répertoire de Forme supérieure, pathologies, rites, Rémanence, Sorcellerie) se fixe **avant l''achat** ; la fiche ne vaut pas accord du MJ. Les phrases destinées au Builder (« le formulaire », « une case cochée », « historisé et payé ») sont retirées des cartes.\n\n### Maîtrise de Fonction\n\n- La Divinité ne s''éveille pas une seconde fois (changer de Dieu est une refonte de l''âme, un événement de scénario). L''équivalent d''une lignée, c''est la **Fonction**, le métier appris dans la Cour.\n- **Une Fonction est maîtrisée quand chacune de ses trois voies a au moins son palier d''entrée** : tu connais tout le métier. (Vampire : un Sang en profondeur ; Garou : deux voies au palier II ; Daemon : le métier en largeur.)\n- **Formation secondaire (3 PTV, éveil d''une seconde Fonction)** : il faut ta Fonction principale maîtrisée, un mentor, du temps et une justification dans la Cour. Tu gagnes l''Empreinte de la seconde Fonction et l''accès à ses voies, achetées normalement. Toujours une seule Divinité et une seule Faveur.\n- **Changements** : prérequis « Fonction principale maîtrisée » ajouté ; texte trois fois répété ramené à une phrase.","traits_gratuits":[{"name":"Âme élue","access":"V/SR/R","effect":"L’âme est liée à sa Divinité et retirée du Cycle ordinaire."},{"name":"Vision des âmes","access":"SR/R","effect":"Lit la nature spirituelle générale d’une créature perçue."},{"name":"Assimilation des prières","access":"SR/R","effect":"Dans un Lieu de Résonance, la Faveur divine peut soutenir une action cohérente avec une Facette."}],"droits_acquis":"Les talents achetés avant les voies restent acquis ; les règles de voie valent pour les achats suivants (décision 20)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_voies', 'Voies', NULL, '{"nature":"daemon","chemin":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_ame_elue', 'Âme élue', NULL, '{"nature":"daemon","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Ancrage de l''Élu et Résonance profonde fusionnés au palier II **à coût constant** (1 + 1). Ordre imposé. Ressort propre : l''Ancrage protège l''âme élue, pas un Mageius (à distinguer de l''Ancrage du Mage)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_talents_communs_de_nature_regard_du_heraut', 'Regard du Héraut', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"après une Vision des âmes réussie, le MJ te donne une information spirituelle de plus que ce que ton DR permettait.","texte_reference":"Après une réussite de Vision des âmes, obtient une information spirituelle supplémentaire pertinente par rapport à ce que le DR aurait normalement donné.","lore":"Vision des âmes cesse d’être une simple classification. L’Élu apprend à remarquer la cicatrice qui trahit un pacte, l’empreinte d’une puissance, une contradiction spirituelle ou le détail qui explique pourquoi cette âme n’est pas exactement ce qu’elle semblait être.","groupe_actuel":"Talents communs de Nature","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_talents_communs_de_nature_ancrage_de_l_elu', 'Lien divin', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"+3 à tes résistances contre la possession, le bannissement, la capture ou le déplacement forcé de ton âme. Et dans un Lieu de Résonance, ta Faveur divine sert 2 fois par scène, jamais deux fois sur le même test.","texte_reference":"+3 aux résistances contre possession, bannissement, capture, altération ou déplacement forcé de l’âme.\nDans un Lieu de Résonance, Faveur divine peut être utilisée deux fois par scène, jamais deux fois sur le même test.","lore":"La Divinité a déjà retiré cette âme du Cycle pour la reforger. Ce lien ancien lui donne une inertie spirituelle inhabituelle : l’arracher à son corps, la déplacer ou la posséder revient à lutter contre la marque même qui l’a faite Héraut.","groupe_actuel":"Talents communs de Nature","statut_regle":"correction","changements":"Fusion de Ancrage de l’Élu et Résonance profonde."}'::jsonb, 'published', ARRAY['daemon_clean_talents_communs_de_nature_resonance_profonde']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_vies_passees', 'Vies passées', NULL, '{"nature":"daemon","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"la Rémanence demande désormais Mémoire des âges (ordre de voie). Un Daemon qui n''est pas Ancien Prophète s''arrête au palier I. Mémoire des âges (vies passées) et Rappel absolu d''Astaroth (cette vie) restent distincts."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_talents_communs_de_nature_memoire_des_ages', 'Mémoire des âges', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":null,"texte_court":"+3 à un test de Savoirs pour te rappeler ce que tu as vécu ou appris dans une ancienne vie ou dans une Cour divine. Aucun jet si c''est évident.","texte_reference":"+3 à un test de Savoirs lorsqu’il s’agit de rappeler une information que le Daemon a personnellement vécue ou apprise dans une ancienne vie ou dans une Cour divine. Aucun jet si le souvenir est évident et incontestable.","lore":"Une Cour divine ne forme pas seulement des serviteurs : elle accumule des vies. Certains souvenirs remontent avec la précision d’une expérience vécue, y compris lorsque l’incarnation présente n’a jamais approché le lieu, la langue ou l’époque concernés.","groupe_actuel":"Talents communs de Nature","statut_regle":"correction","changements":"la Rémanence demande désormais Mémoire des âges (ordre de voie). Un Daemon qui n''est pas Ancien Prophète s''arrête au palier I. Mémoire des âges (vies passées) et Rappel absolu d''Astaroth (cette vie) restent distincts."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_origine_ancien_prophete_remanence_prophetique', 'Rémanence prophétique', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, Ancien Prophète seulement","activation":"Selon la manifestation définie","texte_court":"avec le MJ, une manifestation étroite de la cicatrice de ton ancien Attribut (effet, PA, portée, cadence, limites). Jamais l''Attribut lui-même, jamais de prière. *Exemples* : Victoire, 1/scène, un échec de 3 points ou moins devient une réussite DR 0 ; Force, 1/scène, +3 à un effort de force brute à la limite du possible.","texte_reference":"Exclusif à l’origine Ancien Prophète, rare et soumise à accord MJ. Avant achat, le joueur et le MJ définissent une manifestation étroite : ancien Attribut, effet, PA, portée, cadence, conditions et limites. Le formulaire conserve la description et ne constitue jamais une autorisation MJ. Aucun Attribut cosmique, prière, rang ou pouvoir supplémentaire n’est attribué automatiquement.","lore":"L’âme choisie garde une cicatrice de son ancienne charge cosmique, sans redevenir ce qu’elle portait autrefois.","groupe_actuel":"Origine de l’Élu › Ancien Prophète","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_oracle_tentateur', 'Oracle / Tentateur', NULL, '{"nature":"daemon","chemin":["Oracle / Tentateur"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_telepathie', 'Télépathie', NULL, '{"nature":"daemon","cout":0,"cout_actuel":0,"palier":"empreinte","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"parler en esprit avec une créature consentante perçue à 30 m environ. Elle peut répondre. Aucun accès à ses pensées.","texte_reference":"parler en esprit avec une créature consentante perçue à 30 m environ. Elle peut répondre. Aucun accès à ses pensées.","lore":null,"groupe_actuel":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_oracle_tentateur_lecture_mentale', 'Lecture mentale', NULL, '{"nature":"daemon","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":"lire un esprit, en surface puis en profondeur.","profil":null,"changements":"ressort propre ajouté. Il distingue ces lectures des pouvoirs homonymes du Vampire, du Garou et de l''Angelus."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_oracle_tentateur_lecture_mentale_lecture_superficielle', 'Lecture superficielle', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":"1 PA","texte_court":"Jet de pouvoir contre Défense occulte : l''émotion dominante, l''intention immédiate ou le sujet de pensée actif. Aucun souvenir profond.","texte_reference":"Pour 1 PA en SR ou R, opposez Volonté + Maîtrise spirituelle à la Défense occulte pour saisir l’émotion dominante, l’intention immédiate ou le sujet de pensée actif. Aucun souvenir profond n’est révélé.","lore":"L’Oracle n’ouvre pas l’esprit comme un dossier. Il en effleure la surface : l’émotion qui domine, l’intention qui se forme et la pensée que la cible est déjà en train de tenir deviennent aussi perceptibles qu’une expression du visage.","groupe_actuel":"Oracle / Tentateur › Lecture mentale","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_oracle_tentateur_lecture_mentale_lecture_profonde', 'Lecture profonde', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 2 PA","activation":null,"texte_court":"chercher une information ou un souvenir précis ; le DR fixe la précision. Pas de téléchargement des secrets.","texte_reference":"2 PA. Rechercher une information ou un souvenir précis dans l’esprit d’une cible. Le DR détermine la précision ; pas de téléchargement intégral des secrets.","lore":"Cette fois l’Oracle entre avec une question. Il suit associations, images et résistances jusqu’au souvenir recherché, mais reste tributaire de ce qu’il sait demander : fouiller sans but ne transforme jamais une conscience en archive téléchargeable.","groupe_actuel":"Oracle / Tentateur › Lecture mentale","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_oracle_tentateur_fantasmagorie', 'Fantasmagorie', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"tromper un esprit, jusque dans son sommeil.","profil":null,"changements":"aucun (texte raccourci). Déjà distincte des Fantasmagories du Vampire et de l''Angelus : mentale, une cible, prolongée dans le rêve."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_oracle_tentateur_fantasmagorie_fantasmagorie', 'Fantasmagorie', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"Jet de pouvoir contre Défense occulte : tu imposes à une cible une perception illusoire simple et multisensorielle. Elle est mentale : aucune caméra ne la voit.","texte_reference":"1 PA. Imposer une perception illusoire simple et multisensorielle à une cible. Volonté + Maîtrise spirituelle contre Défense occulte. L’illusion est mentale et n’est normalement pas filmée.","lore":"Le Tentateur impose à l’esprit une perception qui n’existe que pour sa victime, assez cohérente pour devenir momentanément plus convaincante que le monde réel.","groupe_actuel":"Oracle / Tentateur › Fantasmagorie","statut_regle":"correction","changements":"aucun (texte raccourci). Déjà distincte des Fantasmagories du Vampire et de l''Angelus : mentale, une cible, prolongée dans le rêve."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_oracle_tentateur_fantasmagorie_songe_obsedant', 'Songe obsédant', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1/scénario","activation":"Prochain sommeil · 1/scénario","texte_court":"au prochain vrai sommeil d''une cible de ta Fantasmagorie, quelques minutes de dialogue en rêve. Elle répond si elle le veut ; hostile, elle peut refuser (résistance occulte). Ni souvenirs cachés ni pensées tues.","texte_reference":"Une fois par scénario, au prochain sommeil réel d’une cible affectée par votre Fantasmagorie, vous pouvez établir quelques minutes de dialogue onirique et recevoir ses réponses volontaires. Une cible hostile peut refuser par une résistance occulte ; ce lien ne lit ni souvenirs cachés ni pensées non exprimées.\n\nLe dialogue porte sur des réponses volontairement exprimées ; aucune réponse, conviction ou information inconnue n’est créée. Le dépôt d’une image par Rêve empoisonné de Xezbeth reste distinct de ce dialogue.","lore":"Une illusion ne s’arrête plus avec la scène : un fragment s’accroche à la victime et attend son sommeil pour revenir sous forme de rêve, d’image ou de message.","groupe_actuel":"Oracle / Tentateur › Fantasmagorie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_oracle_tentateur_influence_prophetie', 'Influence & prophétie', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"comprendre ce qui touche une personne, et qui la marque.","profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_oracle_tentateur_influence_prophetie_charme_daemoniaque', 'Charme daemoniaque', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"tu observes un interlocuteur et sais quel registre lui parle : +3 à une action sociale cohérente contre lui pour la scène.","texte_reference":"1 PA. Observer un interlocuteur permet de comprendre quel registre affectif ou comportemental lui parlera le mieux. Pour la scène, +3 à une action sociale cohérente contre cette personne.","lore":"L’Oracle apprend à repérer le langage émotionnel auquel son interlocuteur réagira vraiment, puis à parler exactement sur cette fréquence sans lui voler sa volonté.","groupe_actuel":"Oracle / Tentateur › Influence & prophétie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_oracle_tentateur_influence_prophetie_appel_du_prophete', 'Appel du Prophète', NULL, '{"nature":"daemon","cout":2,"cout_actuel":1,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":"Après Vision des âmes","texte_court":"après une Vision des âmes réussie, identifier la Divinité d''une marque connue ou la nature d''un lien divin actif, et ses résonances prophétiques. Une dissimulation spirituelle reste opposable ; ni nom véritable, ni Attribut complet.","texte_reference":"Après une Vision des âmes réussie, identifiez plus précisément la Divinité d’une marque connue ou la nature d’un lien divin actif, ainsi que les résonances prophétiques accessibles. Une dissimulation spirituelle reste opposable et aucun nom véritable ni Attribut complet n’est révélé.\n\nL’effet lit une résonance de la cible : il n’accorde pas l’origine Ancien Prophète ni sa Rémanence au Daemon.","lore":"Certaines âmes résonnent trop fortement avec un principe divin pour passer inaperçues ; l’Oracle apprend à reconnaître cette cicatrice sans prétendre en connaître immédiatement le nom.","groupe_actuel":"Oracle / Tentateur › Influence & prophétie","statut_regle":"correction","changements":"Coût 1 → 2."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_chatiment_tourmenteur', 'Châtiment / Tourmenteur', NULL, '{"nature":"daemon","chemin":["Châtiment / Tourmenteur"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_affliction', 'Affliction', NULL, '{"nature":"daemon","cout":0,"cout_actuel":0,"palier":"empreinte","porte":null,"palier_double":null,"acces":"R, 1 PA, contact","activation":null,"texte_court":"Jet de pouvoir contre Défense occulte : douleur, nausée, faiblesse, vertige ou spasme. −3 à une famille d''actions jusqu''à la fin du prochain round.","texte_reference":"Jet de pouvoir contre Défense occulte : douleur, nausée, faiblesse, vertige ou spasme. −3 à une famille d''actions jusqu''à la fin du prochain round.","lore":null,"groupe_actuel":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_chatiment_tourmenteur_affliction', 'Affliction', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"faire durer le mal, puis le rendre maladie.","profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_chatiment_tourmenteur_affliction_affliction_persistante', 'Affliction persistante', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"une Affliction réussie peut durer la scène. La cible tente Volonté + Force Mentale contre 15 à la fin de chacun de ses rounds pour en sortir.","texte_reference":"Une Affliction réussie peut durer jusqu’à la fin de la scène. La cible peut tenter Volonté + Force Mentale, difficulté 15, à la fin de chacun de ses rounds ; une réussite y met fin.","lore":"Le Tourmenteur apprend à laisser sa sentence dans le corps. La douleur n’est plus l’éclair d’un instant : muscles, nerfs ou souffle continuent de reproduire l’ordre reçu jusqu’à ce que la victime parvienne enfin à briser l’emprise.","groupe_actuel":"Châtiment / Tourmenteur › Affliction","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_chatiment_tourmenteur_affliction_maladie_sacree', 'Maladie sacrée', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 2 PA, contact","activation":"2 PA · contact · profil défini","texte_court":"après opposition occulte, une pathologie surnaturelle définie avant l''usage (symptômes, malus, durée, fin). Pas de propagation collective.","texte_reference":"Pour 2 PA au contact, imposez après opposition occulte une pathologie surnaturelle définie avant usage : symptômes, malus, durée et moyens de résistance ou de fin. Le talent reste distinct d’une propagation collective et n’accorde pas gratuitement les connaissances anatomiques nécessaires à une intervention précise.","lore":"La punition prend une forme que même un médecin peut observer. Fièvre, inflammation, paralysie ou détresse respiratoire deviennent des réalités biologiques ; plus le Daemon veut être précis, plus il doit réellement comprendre l’organisme qu’il condamne.","groupe_actuel":"Châtiment / Tourmenteur › Affliction","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_chatiment_tourmenteur_terreur', 'Terreur', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"la peur qui naît du mal infligé.","profil":null,"changements":"aucun. Le ressort est déjà propre (la peur suit un mal infligé), à distinguer de la Terreur du prédateur du Garou."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_chatiment_tourmenteur_terreur_terreur', 'Terreur', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène","activation":"1 PA · 1/scène · 3 témoins à 10 m","texte_court":"juste après une Affliction ou une blessure que tu as infligée, jusqu''à trois témoins à 10 m. En échec de Défense occulte, ils sont Tendus jusqu''à la fin de leur prochain round. Pas de panique automatique.","texte_reference":"Une fois par scène, pour 1 PA après une Affliction ou une blessure que vous avez réellement infligée, imposez votre Terreur à jusqu’à trois témoins à 10 m. Ceux qui échouent à leur Défense occulte deviennent Tendus jusqu’à la fin de leur prochain round, sans panique automatique.","lore":"Le Tourmenteur ne montre pas nécessairement un monstre ; il touche directement le réflexe qui dit à l’âme qu’elle est en présence de quelque chose qu’elle devrait fuir.","groupe_actuel":"Châtiment / Tourmenteur › Terreur","statut_regle":"correction","changements":"aucun. Le ressort est déjà propre (la peur suit un mal infligé), à distinguer de la Terreur du prédateur du Garou."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_chatiment_tourmenteur_terreur_hantise_du_condamne', 'Hantise du condamné', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":"Marque · 100 m · scénario","texte_court":"jusqu''à la fin du scénario, tu reconnais l''âme d''une victime de ta Terreur et sens sa direction à 100 m. Une protection spirituelle peut masquer le lien.","texte_reference":"Jusqu’à la fin du scénario, vous reconnaissez l’âme d’une victime marquée par votre Terreur et ressentez sa direction approximative à 100 m maximum. Une protection spirituelle adaptée peut masquer le lien ; aucun emplacement exact ni parcours à travers les obstacles n’est fourni.","lore":"La peur laisse une marque. Après avoir brisé un instant la contenance d’une victime, le Châtiment peut encore sentir son âme et laisser sa présence contaminer ses cauchemars.","groupe_actuel":"Châtiment / Tourmenteur › Terreur","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_chatiment_tourmenteur_destruction', 'Destruction', NULL, '{"nature":"daemon","forme":"progression","forme_lot":"progression, entrée au palier II","verrou":"ordre_paliers","portes":null,"identite":"éteindre un pouvoir divin en sacrifiant le sien.","profil":null,"changements":"pas de palier I (coûts d''origine 2 et 3 conservés)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_chatiment_tourmenteur_destruction_destruction_daemoniaque', 'Destruction daemoniaque', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, contact","activation":"1 PA · contact · scène","texte_court":"Jet de pouvoir contre Défense occulte : un talent actif angélique ou daemoniaque identifiable est neutralisé pour la scène, et tu sacrifies pour la scène un de tes propres talents actifs. Ni Empreinte, ni passif, ni Nature entière.","texte_reference":"Pour 1 PA au contact, après un Jet divin contre la Défense occulte, neutralisez pour la scène un Talent actif angélique ou daemoniaque identifiable et l’un de vos propres Talents actifs encore utilisables. Ni Empreinte, ni passif, ni Nature entière ne peut être choisi ; les effets maintenus qui dépendent du Talent ciblé cessent.","lore":"Le Tourmenteur apprend à frapper non plus seulement le corps ou l’esprit, mais l’accès même à une capacité de Vérité active — au prix d’exposer volontairement l’une des siennes.","groupe_actuel":"Châtiment / Tourmenteur › Destruction","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_chatiment_tourmenteur_destruction_briseur_de_heraut', 'Briseur de Héraut', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1/scène","activation":null,"texte_court":"la même chose à 10 m ; à DR 2+, ton talent sacrifié revient au début de ton prochain round, celui de la cible reste éteint jusqu''à la fin de la scène.","texte_reference":"1/scène. Utiliser Destruction daemoniaque à 10 m ; sur DR 2+, le Talent sacrifié du Châtiment revient au début de son prochain round, celui de la cible reste supprimé jusqu’à la fin de la scène.","lore":"À distance, le Châtiment sacrifie une part de sa propre puissance pour arracher temporairement à un autre Héraut l’accès à l’une de ses armes surnaturelles.","groupe_actuel":"Châtiment / Tourmenteur › Destruction","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_chevalier_legionnaire', 'Chevalier / Légionnaire', NULL, '{"nature":"daemon","chemin":["Chevalier / Légionnaire"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_lame_infernale', 'Lame infernale', NULL, '{"nature":"daemon","cout":0,"cout_actuel":0,"palier":"empreinte","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":null,"texte_court":"sacrifie 1 à 3 PV irréductibles (et autant de PV maximum tant qu''elle existe) : Lame divine DGT 7 / 9 / 11, de mêlée ou de tir, liée à toi. Une seule, jamais prêtée, sans munitions.","texte_reference":"sacrifie 1 à 3 PV irréductibles (et autant de PV maximum tant qu''elle existe) : Lame divine DGT 7 / 9 / 11, de mêlée ou de tir, liée à toi. Une seule, jamais prêtée, sans munitions.","lore":null,"groupe_actuel":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_chevalier_legionnaire_lame_infernale', 'Lame infernale', NULL, '{"nature":"daemon","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":"la Lame change de forme puis de nature.","profil":null,"changements":"précision de non-cumul : la même propriété venue d''Arme de guerre (Baal) ne s''ajoute pas."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_chevalier_legionnaire_lame_infernale_arme_changeante', 'Arme changeante', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"1/round, gratuit, change la forme de ta Lame (épée, lance, fusil, arc…). DGT inchangés ; la Compétence suit la forme.","texte_reference":"1/round gratuitement, changer la forme de la Lame infernale : épée, lance, fusil, arc… Le DGT ne change pas ; la Compétence suit la nouvelle forme.","lore":"La Lame infernale répond à une doctrine de guerre plutôt qu’à une forge. Elle devient lance pour tenir un passage, arme de tir pour couvrir une distance ou lame courte dans un espace confiné, sans jamais cesser d’être la même projection de l’âme du Chevalier.","groupe_actuel":"Chevalier / Légionnaire › Lame infernale","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_chevalier_legionnaire_lame_infernale_arme_exaltee', 'Arme exaltée', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"à la manifestation, choisis pour la scène Perforante (ignore 3 Armure), Terrassante ou Entravante.","texte_reference":"À la manifestation de la Lame, choisir pour la scène Perforante, Terrassante ou Entravante selon les effets définis.","lore":"La Lame reçoit une intention supplémentaire — percer, terrasser ou entraver — et cesse d’être seulement une arme puissante pour devenir un outil de doctrine martiale.","groupe_actuel":"Chevalier / Légionnaire › Lame infernale","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_chevalier_legionnaire_armure_infernale', 'Armure infernale', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"payer de sa chair pour couvrir.","profil":null,"changements":"aucun (ressort propre déjà là : la protection se paie en PV maximum)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_chevalier_legionnaire_armure_infernale_armure_infernale', 'Armure infernale', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":null,"texte_court":"sacrifie 1 à 3 PV irréductibles : Armure corporelle 2 / 4 / 6. Ces PV réduisent ton maximum et ne se soignent pas tant que l''Armure existe.","texte_reference":"1 PA. Sacrifier 1 à 3 PV irréductibles : Armure corporelle 2/4/6. Les PV sacrifiés réduisent le maximum et ne peuvent être soignés tant que l’Armure existe.","lore":"Le Légionnaire paie son rempart avec quelque chose que l’ennemi aurait voulu lui prendre : sa propre vitalité. Les PV sacrifiés deviennent une cuirasse spirituelle et rappellent visiblement que servir sa Cour peut signifier convertir sa chair en fortification.","groupe_actuel":"Chevalier / Légionnaire › Armure infernale","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_chevalier_legionnaire_armure_infernale_bastion_daemoniaque', 'Bastion daemoniaque', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"tant que l''Armure est active, un allié au contact ou juste derrière toi reçoit +3 en Défense physique contre les attaques venant du côté protégé.","texte_reference":"Tant que l’Armure infernale est active, un allié au contact ou immédiatement derrière reçoit +3 Défense physique contre les attaques provenant approximativement du côté protégé.","lore":"L’Armure infernale déborde de son porteur : un allié placé dans son ombre peut réellement combattre derrière lui comme derrière un rempart vivant.","groupe_actuel":"Chevalier / Légionnaire › Armure infernale","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_chevalier_legionnaire_garde_devotion', 'Garde & dévotion', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"se mettre entre l''allié et le coup.","profil":null,"changements":"Dernier Rempart entre dans le plafond de survie."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_chevalier_legionnaire_garde_devotion_garde_du_heraut', 'Garde du Héraut', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, Réaction 1 PA","activation":null,"texte_court":"un allié à portée de Déplacement est visé par une attaque physique : tu te déplaces jusqu''à lui et deviens la cible, si le trajet est possible.","texte_reference":"Réaction 1 PA. Lorsqu’un allié à portée de Déplacement est ciblé par une attaque physique, se déplacer immédiatement jusqu’à lui et devenir la cible si le trajet est réellement possible.","lore":"Protéger un autre Élu devient un réflexe de guerre : le Chevalier traverse l’espace disponible pour prendre sur lui l’attaque qui visait son allié.","groupe_actuel":"Chevalier / Légionnaire › Garde & dévotion","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_chevalier_legionnaire_garde_devotion_devotion_infernale', 'Dévotion infernale', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène","activation":null,"texte_court":"pour la scène, tu ignores les effets de Tendu et Paniqué dus aux blessures et les malus de douleur.","texte_reference":"1 PA, 1/scène. Pour le reste de la scène, ignorer les conséquences mécaniques de Tendu et Paniqué dues aux blessures ainsi que les malus provenant de la douleur.","lore":"La douleur, la peur et la blessure cessent temporairement de dicter le rythme du combat ; le Chevalier continue parce que son service compte davantage que ce que son corps réclame.","groupe_actuel":"Chevalier / Légionnaire › Garde & dévotion","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_chevalier_legionnaire_garde_devotion_dernier_rempart', 'Dernier Rempart', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1/scénario","activation":null,"texte_court":"une attaque devrait t''amener au seuil de Mort : tu restes vivant et capable d''agir jusqu''à la fin de ton prochain round. Si personne ne te sauve, tu meurs.","texte_reference":"1/scénario. Lorsqu’une attaque devrait amener le Chevalier à son seuil de Mort, il reste vivant et capable d’agir jusqu’à la fin de son prochain round ; s’il n’est pas sauvé, il meurt ensuite normalement.","lore":"Même une blessure mortelle ne met pas immédiatement fin au devoir : pendant quelques secondes impossibles, le Chevalier reste debout uniquement parce qu’il lui reste encore quelque chose à accomplir.","groupe_actuel":"Chevalier / Légionnaire › Garde & dévotion","statut_regle":"correction","changements":"Dernier Rempart entre dans le plafond de survie."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_alabor_les_eaux_primordiales', 'ALABOR — Les Eaux primordiales', NULL, '{"nature":"daemon","chemin":["ALABOR — Les Eaux primordiales"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_alabor_les_eaux_primordiales_flots', 'Flots', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"l''eau frappe, saisit, déferle.","profil":null,"changements":"portée de Main des Eaux précisée (20 m, comme les deux autres paliers)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'alabor_les_eaux_primordiales_facette_flots_main_des_eaux', 'Main des Eaux', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, 1 PA, 20 m","activation":null,"texte_court":"déplacer violemment une masse liquide visible. En attaque directe : Défense physique, DGT 7.","texte_reference":"Déplacer violemment une masse liquide visible. Une attaque directe utilise DGT 7 et Défense physique.","lore":"Pour un Héraut d’Alabor, l’eau n’est jamais un décor inerte. Une masse liquide proche répond comme un membre immense : elle frappe, renverse ou change brutalement de direction sous l’autorité des Eaux primordiales.","groupe_actuel":"ALABOR — Les Eaux primordiales › Facette : Flots","statut_regle":"correction","changements":"portée de Main des Eaux précisée (20 m, comme les deux autres paliers)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'alabor_les_eaux_primordiales_facette_flots_etreinte_liquide', 'Étreinte liquide', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 20 m","activation":"1 PA · 20 m · scène","texte_court":"Jet de pouvoir contre Défense physique : la cible est emprisonnée dans l''eau pour la scène. Se libérer : 1 PA et Vigueur + Athlétisme contre le résultat initial. Pas de noyade automatique.","texte_reference":"Pour 1 PA, emprisonnez pour la scène une cible dans une masse d’eau suffisante à 20 m maximum, après un Jet divin contre sa Défense physique. Se libérer coûte 1 PA et demande Vigueur + Athlétisme contre le résultat initial ; aucune noyade automatique.","lore":"Alabor enseigne aussi que l’eau gagne souvent sans frapper. Elle se referme autour d’un corps, remplit l’espace disponible et transforme un élément fluide en prison mouvante dont chaque tentative d’évasion nourrit la lutte.","groupe_actuel":"ALABOR — Les Eaux primordiales › Facette : Flots","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'alabor_les_eaux_primordiales_facette_flots_deferlante', 'Déferlante', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 3 PA, 1/scène","activation":"3 PA · 1/scène · rayon 5 m à 20 m","texte_court":"zone de 5 m à 20 m. Un jet contre chaque Défense physique : DGT 12 et recul jusqu''à 3 m.","texte_reference":"Pour 3 PA, une fois par scène, projetez l’eau disponible sur une zone de 5 m de rayon à 20 m maximum : un Jet divin contre chaque Défense physique, DGT 12 et recul jusqu’à 3 m si le terrain le permet. Les dégâts ne surviennent qu’une fois ; les débris et l’eau déplacés restent réels.","lore":"L’eau se rassemble en une masse qui n’a plus rien d’une simple vague. Alabor lui rend le poids des mers anciennes : elle frappe, emporte et redessine le terrain avant de retomber en torrents désordonnés.","groupe_actuel":"ALABOR — Les Eaux primordiales › Facette : Flots","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_alabor_les_eaux_primordiales_pression', 'Pression', NULL, '{"nature":"daemon","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":"le poids des abysses, qui écrase de plus en plus.","profil":null,"changements":"Écrasement hydrostatique (entrée incomplète : ni PA, ni défense) devient l''amélioration de Poids des Abysses ; portée précisée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'alabor_les_eaux_primordiales_facette_pression_poids_des_abysses', 'Poids des Abysses', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, 1 PA, 20 m","activation":null,"texte_court":"pression localisée, DGT 7. Défense occulte si elle vise directement l''organisme, sinon Défense physique.","texte_reference":"Imposer une pression localisée. DGT 7. Défense occulte si l’effet est appliqué directement à l’organisme.","lore":"La pression d’Alabor se concentre sur un point précis et serre sans avoir besoin d’eau visible. Le corps ressent la profondeur avant de la comprendre : poitrine, articulations et souffle protestent sous un océan absent.","groupe_actuel":"ALABOR — Les Eaux primordiales › Facette : Pression","statut_regle":"correction","changements":"Écrasement hydrostatique (entrée incomplète : ni PA, ni défense) devient l''amélioration de Poids des Abysses ; portée précisée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'alabor_les_eaux_primordiales_facette_pression_ecrasement_hydrostatique', 'Écrasement hydrostatique', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"ton Poids des Abysses inflige DGT 10 et ignore 3 Armure ou Protection cohérente ; il est redoutable contre les objets et les structures.","texte_reference":"DGT 10 et ignore 3 Armure/Protection cohérente ; particulièrement efficace contre objets et structures.","lore":"Le Héraut applique la logique implacable des grandes profondeurs à une matière qui n’a jamais été conçue pour les supporter. Parois, blindages et structures gémissent comme une coque descendue beaucoup trop bas.","groupe_actuel":"ALABOR — Les Eaux primordiales › Facette : Pression","statut_regle":"correction","changements":"Écrasement hydrostatique (entrée incomplète : ni PA, ni défense) devient l''amélioration de Poids des Abysses ; portée précisée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'alabor_les_eaux_primordiales_facette_pression_fond_des_oceans', 'Fond des Océans', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 3 PA, 1/scène","activation":"3 PA · 1/scène · rayon 5 m à 20 m","texte_court":"zone de 5 m à 20 m. Un jet contre chaque Défense occulte : DGT 12. Jusqu''à la fin de la scène, traverser la zone coûte le double de distance.","texte_reference":"Pour 3 PA, une fois par scène, imposez DGT 12 par pression directe dans une zone de 5 m de rayon à 20 m, avec un Jet divin contre chaque Défense occulte. Jusqu’à la fin de la scène, traverser cette zone consomme deux fois la distance normale, sans nouveaux dégâts automatiques.","lore":"L’espace se charge soudain du poids des profondeurs. Respirer, bouger et tenir debout deviennent des actes contre une mer invisible, comme si un morceau d’abysse avait été posé sur le monde de la surface.","groupe_actuel":"ALABOR — Les Eaux primordiales › Facette : Pression","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_alabor_les_eaux_primordiales_pluie_fecondite', 'Pluie & Fécondité', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"donner ou retirer l''eau.","profil":null,"changements":"aucun. Écart de source : 2 PA sur le site, 3 PA dans le livre V6 et le catalogue (on garde le site)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'alabor_les_eaux_primordiales_facette_pluie_fecondite_appel_de_la_pluie', 'Appel de la pluie', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"créer, renforcer ou arrêter une pluie locale raisonnable, si les conditions le permettent.","texte_reference":"Créer, intensifier ou stopper une pluie locale raisonnable lorsque les conditions le permettent.","lore":"L’Élu sent l’humidité disponible comme une réserve suspendue au-dessus du monde. Il invite les nuages à lâcher leur eau — ou à la retenir — jusqu’à ce que le ciel retrouve le rythme de pluie voulu.","groupe_actuel":"ALABOR — Les Eaux primordiales › Facette : Pluie & Fécondité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'alabor_les_eaux_primordiales_facette_pluie_fecondite_eaux_nourricieres', 'Eaux nourricières', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":"10 minutes · 1/jour","texte_court":"après 10 minutes à préparer une zone irriguée de 10 m, une heure de croissance végétale y vaut une journée ; le prochain repos des bénéficiaires rend 2 PV de plus. Une fois par jour par zone ou personne.","texte_reference":"Après dix minutes de préparation d’une zone irriguée de 10 m de rayon, une heure de croissance végétale naturelle y équivaut à une journée et le prochain repos récupérateur de ses bénéficiaires rend 2 PV supplémentaires. Une même zone ou personne n’en bénéficie qu’une fois par jour ; ni nourriture instantanée ni guérison en combat.","lore":"Cette eau ne se contente pas d’humecter le sol. Là où elle pénètre, graines, racines et organismes épuisés retrouvent un élan de croissance, comme si la pluie rapportait avec elle une mémoire de la fertilité première.","groupe_actuel":"ALABOR — Les Eaux primordiales › Facette : Pluie & Fécondité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'alabor_les_eaux_primordiales_facette_pluie_fecondite_deluge', 'Déluge', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":"2 PA · 1/scène · rayon 15 m à 30 m","texte_court":"pluie torrentielle de 15 m de rayon à 30 m, pour la scène. −3 aux tirs et à la vue qui la traversent, déplacements au double, flammes ordinaires éteintes.","texte_reference":"Pour 2 PA, une fois par scène, installez une pluie torrentielle dans un rayon de 15 m à 30 m maximum jusqu’à la fin de la scène. Les tirs et perceptions visuelles qui la traversent subissent −3, les déplacements y consomment deux fois la distance normale et les flammes ordinaires s’éteignent.","lore":"La pluie devient un rideau continu, lourd au point de transformer rues, terre et visibilité. Ce n’est plus un mauvais temps : c’est l’eau d’Alabor qui reprend momentanément possession de tout ce que les hommes croyaient sec.","groupe_actuel":"ALABOR — Les Eaux primordiales › Facette : Pluie & Fécondité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_astaroth_la_civilisation', 'ASTAROTH — La Civilisation', NULL, '{"nature":"daemon","chemin":["ASTAROTH — La Civilisation"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_astaroth_la_civilisation_savoir', 'Savoir', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"tout retenir, tout relier.","profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'astaroth_la_civilisation_facette_savoir_rappel_absolu', 'Rappel absolu', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":null,"texte_court":"ce que tu as appris dans cette vie te revient sans erreur. 1/scène, +3 à un test de Savoirs si tu as une source pertinente.","texte_reference":"Tout ce que le Daemon a réellement appris depuis sa refonte peut être rappelé sans erreur. 1/scène : +3 à un test de Savoirs pour lequel il possède une source pertinente.","lore":"Astaroth ne confond pas érudition et omniscience. Ce que l’Élu a réellement étudié, lui, peut toutefois être conservé sans l’érosion ordinaire de la mémoire : textes, formules et détails deviennent les briques stables d’une civilisation intérieure.","groupe_actuel":"ASTAROTH — La Civilisation › Facette : Savoir","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'astaroth_la_civilisation_facette_savoir_comprehension_universelle', 'Compréhension universelle', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":"Étude préalable · scène","texte_court":"après étude d''une documentation, choisis un domaine : +3 à tes tests de connaissance dans ce domaine pour la scène. Ni pratique ni faculté physique.","texte_reference":"Après étude d’une documentation pertinente, choisissez un domaine de connaissance : vos tests de connaissance dans ce domaine gagnent +3 pour la scène, même si vous y étiez déjà compétent. Cela ne fournit ni expérience pratique ni faculté physique et ne cumule pas un autre +3 équivalent.","lore":"La Civilisation a produit des méthodes avant de produire des réponses. Après assez de lecture, le Daemon sait reconstruire la grammaire d’un domaine inconnu et commencer à raisonner comme un novice formé, sans prétendre posséder l’expérience pratique qui lui manque.","groupe_actuel":"ASTAROTH — La Civilisation › Facette : Savoir","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'astaroth_la_civilisation_facette_savoir_convergence_des_savoirs', 'Convergence des savoirs', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène","activation":"1 PA · 1/scène","texte_court":"le MJ indique un lien nouveau déductible de tes sources. Le test qui l''exploite gagne 2 DR s''il réussit (maximum DR 5). Aucune preuve créée.","texte_reference":"Une fois par scène, après 1 PA de réflexion, le MJ indique un lien nouveau réellement déductible des sources que vous avez étudiées. Le test intellectuel qui exploite cette conclusion gagne 2 DR en cas de réussite, maximum DR 5, sans créer de preuve absente.","lore":"Bibliothèques, souvenirs, leçons et expériences cessent un instant d’être des tiroirs séparés. L’esprit de l’Élu fait remonter le fragment déjà connu qui éclaire le mieux la situation présente, comme une référence retrouvée exactement au bon rayon.","groupe_actuel":"ASTAROTH — La Civilisation › Facette : Savoir","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_astaroth_la_civilisation_ecriture', 'Écriture', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"l''écrit qui lie.","profil":null,"changements":"aucun (Parole fixée reste l''entrée de la voie, sans fusion)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'astaroth_la_civilisation_facette_ecriture_parole_fixee', 'Parole fixée', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"inscrire un message qu''on ne peut altérer sans laisser une trace surnaturelle évidente.","texte_reference":"Inscrire un message qui ne peut être altéré sans laisser une trace surnaturelle évidente.","lore":"Sous la marque d’Astaroth, l’écrit devient témoin de sa propre intégrité. On peut raturer, gratter ou falsifier le message, mais jamais effacer parfaitement l’histoire de cette altération : le texte conserve la cicatrice de la main qui l’a trahi.","groupe_actuel":"ASTAROTH — La Civilisation › Facette : Écriture","statut_regle":"correction","changements":"aucun (Parole fixée reste l''entrée de la voie, sans fusion)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'astaroth_la_civilisation_facette_ecriture_serment_ecrit', 'Serment écrit', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"des signataires consentants lient un engagement écrit ; tu sais quand l''un d''eux le viole volontairement, et lequel.","texte_reference":"Des signataires consentants lient un engagement écrit ; le Daemon sait lorsqu’un signataire le viole volontairement et lequel.","lore":"Le contrat n’est puissant que parce que ceux qui le signent acceptent d’y déposer leur parole. Dès lors, la rupture volontaire résonne dans l’écriture elle-même et désigne au Héraut lequel des engagés a choisi de renier ce qui était consenti.","groupe_actuel":"ASTAROTH — La Civilisation › Facette : Écriture","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'astaroth_la_civilisation_facette_ecriture_uvre_de_civilisation', 'Œuvre de civilisation', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R","activation":"Préparation et étude · scène","texte_court":"un traité, un plan ou un enseignement que tu as réellement préparé donne à ses lecteurs sérieux +3 aux tests fondés sur son contenu, pendant une scène d''application. Aucune compétence absente.","texte_reference":"Un traité, plan ou enseignement que vous avez réellement préparé permet à ses lecteurs sérieux de bénéficier de +3 aux tests directement fondés sur son contenu pendant une scène d’application. Ce bénéfice ne fournit aucune compétence absente et ne se cumule pas avec un ouvrage équivalent.","lore":"Un traité, un plan ou un enseignement longuement façonné devient plus qu’un support : il ordonne la pensée de ceux qui l’étudient. Astaroth fait de la transmission une architecture où une idée complexe peut survivre intacte à son auteur.","groupe_actuel":"ASTAROTH — La Civilisation › Facette : Écriture","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_astaroth_la_civilisation_arts_creation', 'Arts & Création', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"inspirer, transmettre, inventer.","profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'astaroth_la_civilisation_facette_arts_creation_inspiration', 'Inspiration', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"toi ou un allié, +3 à une création artistique ou intellectuelle précise.","texte_reference":"Soi-même ou un allié reçoit +3 à une création artistique ou intellectuelle précise.","lore":"Astaroth souffle moins une idée toute faite qu’un ordre soudain dans le chaos des possibilités. Un geste, une formule ou une composition trouve sa direction, et la création paraît enfin savoir ce qu’elle cherchait à devenir.","groupe_actuel":"ASTAROTH — La Civilisation › Facette : Arts & Création","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'astaroth_la_civilisation_facette_arts_creation_muse_divine', 'Muse divine', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":"Œuvre · scène","texte_court":"ton œuvre transmet vraiment l''émotion ou l''idée choisie, même sans langue commune : +3 au premier test social qui exploite ce message auprès de son public dans la scène. Pour influencer un public hostile : Jet de pouvoir contre Défense occulte ; ni obéissance ni faux souvenir.","texte_reference":"Votre œuvre communique réellement l’émotion ou l’idée choisie, même au-delà d’une barrière de langue, et donne +3 au premier test social qui exploite ce message auprès de son public dans la scène. Une influence hostile exige un Jet divin contre la Défense occulte ; elle ne crée ni obéissance ni faux souvenir.","lore":"L’œuvre devient un véhicule de civilisation autant qu’un objet esthétique. Forme, rythme et symbole portent une intention assez nette pour que le public ne se contente plus de regarder : il ressent réellement ce que l’auteur a voulu transmettre.","groupe_actuel":"ASTAROTH — La Civilisation › Facette : Arts & Création","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'astaroth_la_civilisation_facette_arts_creation_etincelle_de_genie', 'Étincelle de génie', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1/scénario","activation":null,"texte_court":"sur un projet vraiment nouveau, une réussite devient au moins DR 3. Il faut les connaissances.","texte_reference":"Sur un projet créatif, scientifique ou technique réellement nouveau, transformer une réussite en DR 3 minimum. Les connaissances nécessaires restent obligatoires.","lore":"Face à un problème neuf, des éléments jusque-là séparés s’emboîtent soudain. L’Élu ne reçoit pas un savoir qu’il n’a jamais appris ; il voit la combinaison fertile que son expérience et sa créativité rendaient déjà possible.","groupe_actuel":"ASTAROTH — La Civilisation › Facette : Arts & Création","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_belial_la_reine_des_dieux', 'BELIAL — La Reine des Dieux', NULL, '{"nature":"daemon","chemin":["BELIAL — La Reine des Dieux"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_belial_la_reine_des_dieux_feu_royal', 'Feu royal', NULL, '{"nature":"daemon","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":"un feu qu''on n''éteint pas.","profil":null,"changements":"aucun (Feu inexorable est faible, gardé tel quel)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belial_la_reine_des_dieux_facette_feu_royal_flamme_souveraine', 'Flamme souveraine', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, 1 PA, 30 m","activation":null,"texte_court":"Jet de pouvoir contre Défense physique, DGT 7.","texte_reference":"Attaque de Feu divin à 30 m. Volonté + Maîtrise spirituelle contre Défense physique. DGT 7.","lore":"Le feu de Belial n’est pas un incendie accidentel : il arrive comme un ordre. La Flamme souveraine désigne une cible et projette contre elle une chaleur divine dont l’apparition a autant du décret royal que de la combustion.","groupe_actuel":"BELIAL — La Reine des Dieux › Facette : Feu royal","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belial_la_reine_des_dieux_facette_feu_royal_feu_inexorable', 'Feu inexorable', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R — prérequis Flamme souveraine","activation":null,"texte_court":"ta Flamme souveraine ignore jusqu''à 3 points de protection fondée sur la chaleur ou le feu ; ses feux persistants résistent aux moyens ordinaires.","texte_reference":"Les manifestations persistantes de Feu divin sont difficiles à étouffer par des moyens ordinaires. Flamme souveraine ignore jusqu’à 3 points de protection spécifiquement fondée sur la chaleur ou le feu.","lore":"Une fois reconnu par la Reine, ce feu refuse de mourir comme une flamme ordinaire. L’étouffer, le refroidir ou lui opposer une protection thermique devient une négociation perdue d’avance avec une manifestation qui se considère légitime.","groupe_actuel":"BELIAL — La Reine des Dieux › Facette : Feu royal","statut_regle":"correction","changements":"aucun (Feu inexorable est faible, gardé tel quel)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belial_la_reine_des_dieux_facette_feu_royal_colere_de_la_reine', 'Colère de la Reine', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 3 PA, 1/scène","activation":null,"texte_court":"zone d''environ 10 m à 40 m. Un jet contre chaque Défense physique, DGT 12. Tu peux épargner quelques individus clairement identifiés.","texte_reference":"Zone visible d’environ 10 m de rayon jusqu’à 40 m. Un seul jet ; chaque cible compare sa Défense physique. DGT 12, Feu divin. Le Daemon peut exclure quelques individus clairement identifiés, pas sculpter une zone de précision parfaite.","lore":"La colère de Belial ne prend plus la forme d’une flamme tenue en main. Un espace entier s’embrase sous un feu de cour divine, assez discipliné pour épargner quelques figures désignées mais trop vaste pour ressembler à un simple projectile.","groupe_actuel":"BELIAL — La Reine des Dieux › Facette : Feu royal","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_belial_la_reine_des_dieux_domination', 'Domination', NULL, '{"nature":"daemon","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":"l''ordre d''une reine.","profil":null,"changements":"une Injonction par cible et par round (le contrôle était illimité pour 1 PA). Ressort propre explicité : un ordre royal, prononcé et compris. Il distingue l''Injonction de la Domination du Vampire (le regard, via la Fascination), du Regard d''Alpha du Garou (la peur) et de l''Ordre impérieux Krovni (le combat)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belial_la_reine_des_dieux_facette_domination_injonction_souveraine', 'Injonction souveraine', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"à voix haute, dans une langue que la cible comprend, Charisme + Autorité contre Défense occulte : un ordre simple force sa prochaine action (« Arrête », « Lâche », « Recule »). Rien de suicidaire ni de mutilant. **Une seule Injonction par cible et par round.**","texte_reference":"Charisme + Autorité + 1d10e contre Défense occulte. Un ordre simple et compréhensible force la prochaine action disponible de la cible : « Arrête », « Lâche », « Recule », etc. Pas d’acte manifestement suicidaire ou de mutilation majeure.","lore":"Quelques mots prononcés avec l’autorité de la Reine pèsent plus lourd qu’une simple menace. Le corps hésite avant l’esprit et cherche à accomplir l’ordre immédiat, tant que celui-ci reste compréhensible et ne réclame pas l’impensable.","groupe_actuel":"BELIAL — La Reine des Dieux › Facette : Domination","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belial_la_reine_des_dieux_facette_domination_decret_royal', 'Décret royal', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"un interdit simple jusqu''à la fin de la scène. À chaque tentative directe de le violer, la cible refait une Défense occulte active sans payer de PA ; une réussite le brise.","texte_reference":"Imposer un interdit simple jusqu’à la fin de la scène. À chaque tentative directe de violation, la cible peut refaire une Défense occulte active sans coût de PA ; une réussite brise définitivement le Décret.","lore":"Le décret de Belial transforme un interdit clairement énoncé en présence suspendue sur la scène. Celui qui tente de le franchir sent l’ordre se dresser devant sa volonté ; le refus reste possible, mais il exige de briser cette souveraineté.","groupe_actuel":"BELIAL — La Reine des Dieux › Facette : Domination","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belial_la_reine_des_dieux_facette_domination_souverainete_de_belial', 'Souveraineté de Belial', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":null,"texte_court":"la même Injonction à toutes les créatures choisies à 15 m qui t''entendent et te comprennent. Un jet, chacune oppose sa Défense occulte.","texte_reference":"Donner une même Injonction souveraine à toutes les créatures choisies dans un rayon de 15 m capables d’entendre et comprendre. Un seul jet de Charisme + Autorité ; chaque cible oppose sa Défense occulte.","lore":"La présence royale cesse de viser un seul interlocuteur. Une même injonction roule sur l’assemblée comme un commandement de cour, obligeant chacun à confronter sa propre volonté au poids de Belial.","groupe_actuel":"BELIAL — La Reine des Dieux › Facette : Domination","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_belial_la_reine_des_dieux_destruction', 'Destruction', NULL, '{"nature":"daemon","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":"briser ce qui protège.","profil":null,"changements":"Anéantissement ramené à une ligne (règle répétée trois fois). Écart de source : 2 PA sur le site, 3 PA dans le livre V6 et le catalogue."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belial_la_reine_des_dieux_facette_destruction_fracture_souveraine', 'Fracture souveraine', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, 1 PA, 20 m","activation":null,"texte_court":"contre un objet, une structure, une protection matérielle ou une construction surnaturelle visible : DGT 9, ignore 3 Armure ou Protection. Contre une créature vivante : Défense occulte, DGT 6.","texte_reference":"Cibler objet, structure, protection matérielle ou construction surnaturelle visible à 20 m. DGT 9 et ignore 3 Armure/Protection. Contre une créature vivante directement : Défense occulte, DGT 6.","lore":"Le Héraut désigne une structure et lui impose l’idée qu’elle peut rompre. Les constructions surnaturelles ne sont pas épargnées : leur cohérence se fend sous la même autorité qui ferait éclater une porte ou un mur.","groupe_actuel":"BELIAL — La Reine des Dieux › Facette : Destruction","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belial_la_reine_des_dieux_facette_destruction_briseur_de_defenses', 'Briseur de défenses', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R — prérequis Fracture souveraine","activation":null,"texte_court":"quand un pouvoir de Belial inflige au moins 1 dégât après Protection, une protection identifiable perd 2 points jusqu''à la fin de la scène (une fois par protection et par scène).","texte_reference":"Lorsqu’un pouvoir de Belial inflige au moins 1 dégât après Protection, compromettre une protection identifiable : −2 Armure/Protection correspondante jusqu’à la fin de la scène. Une même protection ne peut être réduite ainsi qu’une fois par scène par ce Daemon.","lore":"Une protection touchée par Belial garde la trace de l’impact. Fissure, chaleur ou faille occulte demeure exploitable pour le reste de l’affrontement, comme si la Reine avait publiquement démontré où cette défense pouvait être humiliée.","groupe_actuel":"BELIAL — La Reine des Dieux › Facette : Destruction","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belial_la_reine_des_dieux_facette_destruction_aneantissement', 'Anéantissement', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":"2 PA · 1/scène","texte_court":"cible unique. Objet, structure ou barrière : DGT 15, ignore 6 Protection. Créature : Défense occulte, DGT 12, ignore 3 Protection. Jamais une protection mythique ni un artefact majeur détruit d''office.","texte_reference":"Pour 2 PA, toujours une fois par scène : DGT 15 et pénétration 6 contre objet ou barrière, DGT 12 et pénétration 3 contre une créature. La Défense et la Protection adaptées restent applicables ; aucun artefact majeur n’est supprimé automatiquement.\n\nObjet, structure ou barrière : Protection adaptée. Une attaque directe contre une créature oppose la Défense occulte. Le pouvoir ne détruit pas automatiquement une protection mythique.","lore":"Belial concentre ici sa souveraineté dans le droit de défaire. La cible paraît momentanément privée de la solidité qu’elle croyait acquise : pierre, barrière ou chair rencontrent une puissance conçue pour laisser une absence là où se dressait une résistance.","groupe_actuel":"BELIAL — La Reine des Dieux › Facette : Destruction","statut_regle":"correction","changements":"Anéantissement ramené à une ligne (règle répétée trois fois). Écart de source : 2 PA sur le site, 3 PA dans le livre V6 et le catalogue."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_diablo_la_nuit_qui_regarde', 'DIABLO — La Nuit qui regarde', NULL, '{"nature":"daemon","chemin":["DIABLO — La Nuit qui regarde"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_diablo_la_nuit_qui_regarde_nuit', 'Nuit', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"être chez soi dans le noir.","profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'diablo_la_nuit_qui_regarde_facette_nuit_enfant_de_l_inconnu', 'Enfant de l''Inconnu', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"en pénombre ou dans l''obscurité, +3 en Furtivité et vision parfaite sans lumière.","texte_reference":"En pénombre ou obscurité : +3 Furtivité et vision parfaite malgré l’absence de lumière ordinaire.","lore":"Diablo apprend à ses Hérauts que l’obscurité est un territoire, pas une absence. Là où l’œil humain perd ses repères, le Daemon retrouve au contraire des contours nets et une manière de se déplacer que la lumière rendrait presque maladroite.","groupe_actuel":"DIABLO — La Nuit qui regarde › Facette : Nuit","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'diablo_la_nuit_qui_regarde_facette_nuit_pas_dans_la_nuit', 'Pas dans la Nuit', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":null,"texte_court":"passer d''une ombre assez grande à une autre ombre visible, jusqu''à 20 m.","texte_reference":"Passer d’une ombre suffisamment grande à une autre visible jusqu’à 20 m.","lore":"Deux ombres assez profondes peuvent devenir les bords d’un même passage. Le Daemon s’efface de l’une et ressort de l’autre sans traverser visiblement l’espace intermédiaire, comme si la Nuit avait momentanément replié sa propre géographie.","groupe_actuel":"DIABLO — La Nuit qui regarde › Facette : Nuit","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'diablo_la_nuit_qui_regarde_facette_nuit_nuit_absolue', 'Nuit absolue', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":"2 PA · 1/scène · rayon 15 m","texte_court":"obscurité divine de 15 m centrée sur toi, pour la scène. Tu y vois ; les autres ont besoin d''une perception surnaturelle adaptée ; les lumières ordinaires n''y marchent pas.","texte_reference":"Pour 2 PA, une fois par scène, créez jusqu’à la fin de la scène une obscurité divine de 15 m de rayon centrée sur vous à l’activation. Vous y voyez ; les autres doivent posséder une perception surnaturelle adaptée, et les lumières ordinaires n’y fonctionnent pas.","lore":"Diablo ferme localement le monde à la lumière ordinaire. L’obscurité n’est plus un manque d’éclairage mais une substance divine qui étouffe les sources communes et ne cède qu’aux perceptions réellement capables de regarder dans la Nuit.","groupe_actuel":"DIABLO — La Nuit qui regarde › Facette : Nuit","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_diablo_la_nuit_qui_regarde_cauchemar', 'Cauchemar', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"la peur sans visage.","profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'diablo_la_nuit_qui_regarde_facette_cauchemar_peur_sans_visage', 'Peur sans visage', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"Jet de pouvoir contre Défense occulte : la cible est au moins Tendue jusqu''à la fin du prochain round.","texte_reference":"Volonté + Maîtrise spirituelle contre Défense occulte. Sur réussite, la cible est au minimum Tendue par la peur jusqu’à la fin du prochain round.","lore":"Aucune créature précise n’est nécessaire. Le Héraut ouvre simplement dans l’esprit la certitude qu’une chose terrible approche, laissant l’instinct remplir le vide avec ce que la cible redoute le plus.","groupe_actuel":"DIABLO — La Nuit qui regarde › Facette : Cauchemar","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'diablo_la_nuit_qui_regarde_facette_cauchemar_cauchemar_eveille', 'Cauchemar éveillé', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 20 m","activation":"1 PA · 20 m · scène","texte_court":"Jet contre Défense occulte : −3 aux actions de calme ou de concentration pour la scène. La cible peut, 1 PA une fois par round, tenter Volonté + Force Mentale contre le résultat initial pour s''en libérer.","texte_reference":"Pour 1 PA, imposez à une cible à 20 m un cauchemar personnel après un Jet divin contre sa Défense occulte : −3 aux actions exigeant calme ou concentration pour la scène. Elle peut consacrer 1 PA, une fois par round, à Volonté + Force Mentale contre le résultat initial pour y mettre fin.","lore":"Diablo donne à la peur une silhouette choisie par la victime elle-même. Le cauchemar s’installe dans l’état de veille, assez intime pour détourner l’attention et assez persistant pour que la cible doive lutter contre sa propre imagination.","groupe_actuel":"DIABLO — La Nuit qui regarde › Facette : Cauchemar","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'diablo_la_nuit_qui_regarde_facette_cauchemar_terreur_primordiale', 'Terreur primordiale', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":"2 PA · 1/scène · 10 m","texte_court":"cibles choisies et perçues à 10 m, un jet contre chaque Défense occulte : Paniquées un round, puis Tendues pour la scène. Même sortie que ci-dessus.","texte_reference":"Pour 2 PA, une fois par scène, les cibles choisies et perçues à 10 m affrontent le même Jet divin avec leur Défense occulte : en échec, elles sont Paniquées pendant un round puis Tendues pour la scène. Elles peuvent ensuite briser l’effet par 1 PA et Volonté + Force Mentale contre le résultat initial, une fois par round.","lore":"La peur cesse d’être personnelle et traverse le groupe comme un réflexe de proie. Chacun peut lui donner un visage différent, mais tous reçoivent le même message ancestral : quelque chose ici est assez dangereux pour justifier la panique.","groupe_actuel":"DIABLO — La Nuit qui regarde › Facette : Cauchemar","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_diablo_la_nuit_qui_regarde_devoration', 'Dévoration', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"manger ce qui s''oppose à la Nuit.","profil":null,"changements":"« Opposition appropriée » précisée : Jet de pouvoir contre la Puissance de l''effet."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'diablo_la_nuit_qui_regarde_facette_devoration_mange_lumiere', 'Mange-lumière', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"absorber une source de lumière ou un effet lumineux mineur visible.","texte_reference":"Absorber une source lumineuse ou un effet lumineux mineur visible.","lore":"La lumière visible se contracte vers le Héraut comme une nourriture aspirée. Ampoule, flamme ou éclat surnaturel mineur perd son rayonnement, et l’obscurité qui reste paraît plus épaisse d’avoir réellement consommé quelque chose.","groupe_actuel":"DIABLO — La Nuit qui regarde › Facette : Dévoration","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'diablo_la_nuit_qui_regarde_facette_devoration_la_nuit_apprend', 'La Nuit apprend', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":"Deux usages de l’Écho · scène","texte_court":"un Écho de ta Rémanence nocturne peut être reproduit deux fois avant la fin de la scène, au coût de sa version élémentaire.","texte_reference":"Un Écho obtenu par Rémanence nocturne peut être reproduit deux fois avant la fin de la scène, au coût normal de sa version élémentaire. Cela ne copie ni un Sang complet ni les ressources, prérequis biologiques ou pouvoirs uniques du porteur d’origine.","lore":"Ce que la Nuit dévore ne disparaît pas toujours immédiatement. Diablo en laisse une rémanence plus stable dans son Élu, assez longtemps pour que la propriété capturée puisse être comprise, répétée et imitée avec davantage de fidélité.","groupe_actuel":"DIABLO — La Nuit qui regarde › Facette : Dévoration","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'diablo_la_nuit_qui_regarde_facette_devoration_predateur_des_tenebres', 'Prédateur des Ténèbres', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, Réaction, 1/scène","activation":null,"texte_court":"quand un pouvoir de Vampire ou d''Ombre te vise directement : Jet de pouvoir contre sa Puissance. Si tu gagnes, il est annulé contre toi et tu en gardes l''Écho.","texte_reference":"Lorsqu’un pouvoir de Vampire ou d’Ombre le prend directement pour cible, effectuer une opposition appropriée. En gagnant, l’effet est annulé contre le Daemon et il en obtient l’Écho.","lore":"Lorsqu’une puissance d’ombre cherche à le saisir, l’Élu répond en prédateur plutôt qu’en victime. Il peut happer la manifestation au moment du contact et en conserver l’écho, comme si la Nuit reconnaissait ce qui lui ressemble pour mieux le manger.","groupe_actuel":"DIABLO — La Nuit qui regarde › Facette : Dévoration","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_lilith_desir_sexe_plaisir_et_attachement', 'LILITH — Désir, Sexe, Plaisir et Attachement', NULL, '{"nature":"daemon","chemin":["LILITH — Désir, Sexe, Plaisir et Attachement"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_lilith_desir_sexe_plaisir_et_attachement_desir_plaisir', 'Désir & Plaisir', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"voir le désir, l''attiser, le retirer.","profil":null,"changements":"Grâce retirée bornée au scénario (« voire plus longtemps » supprimé). Les trois rappels de consentement d''Éveiller le désir réduits à un."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lilith_desir_sexe_plaisir_et_attachement_facette_desir_plaisir_voir_le_desir', 'Voir le désir', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"en observant quelqu''un quelques instants, tu perçois ce qu''il désire maintenant. Pas ses secrets profonds.","texte_reference":"En observant quelqu’un quelques instants, percevoir ce qu’il désire actuellement sans accéder automatiquement à ses secrets profonds.","lore":"Lilith ne donne pas accès à une liste de secrets ; elle rend lisible la tension qui attire réellement une personne. Faim de reconnaissance, plaisir, affection ou envie immédiate se dessinent alors derrière les mots sans devenir pour autant une confession forcée.","groupe_actuel":"LILITH — Désir, Sexe, Plaisir et Attachement › Facette : Désir & Plaisir","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lilith_desir_sexe_plaisir_et_attachement_facette_desir_plaisir_eveiller_le_desir', 'Éveiller le désir', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":"1 PA · scène","texte_court":"Charisme + Influence ou Diplomatie contre Défense occulte : un désir possible s''intensifie ; +3 aux tests sociaux qui l''exploitent pour la scène. La cible garde ses limites ; un sentiment n''est jamais un consentement.","texte_reference":"Pour 1 PA, après opposition à la Défense occulte, intensifiez un désir réellement possible chez la cible et gagnez +3 aux tests sociaux qui l’exploitent pendant la scène. Elle conserve ses limites et peut refuser ; ni orientation, ni consentement, ni personnalité ne sont réécrits.\n\nJet : Charisme + Influence ou Diplomatie + 1d10e contre Défense occulte. Un sentiment n’est jamais un consentement ni une injonction automatique.","lore":"Le Héraut ne crée pas une personnalité qui n’existait pas. Il souffle sur une braise réelle : un désir déjà possible prend assez de place pour peser sur les décisions de la scène, tout en laissant à la cible ses limites, son orientation et sa volonté.","groupe_actuel":"LILITH — Désir, Sexe, Plaisir et Attachement › Facette : Désir & Plaisir","statut_regle":"correction","changements":"Grâce retirée bornée au scénario (« voire plus longtemps » supprimé). Les trois rappels de consentement d''Éveiller le désir réduits à un."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lilith_desir_sexe_plaisir_et_attachement_facette_desir_plaisir_grace_retiree', 'Grâce retirée', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 2 PA, 1/scène","activation":null,"texte_court":"Jet contre Défense occulte : jusqu''à la fin du scénario, la cible ne ressent plus aucun plaisir (nourriture, sexe, réussite, drogues, affection).","texte_reference":"Défense occulte. Priver une cible de toute sensation de plaisir jusqu’à la fin du scénario, voire plus longtemps si la fiction le justifie. Nourriture, sexe, réussite, drogues ou affection n’apportent plus de satisfaction.","lore":"Lilith peut retirer ce qu’elle accorde : la capacité même à goûter la satisfaction. La cible continue de manger, gagner, toucher ou être aimée, mais chacune de ces expériences arrive dans un esprit où le plaisir ne se lève plus.","groupe_actuel":"LILITH — Désir, Sexe, Plaisir et Attachement › Facette : Désir & Plaisir","statut_regle":"correction","changements":"Grâce retirée bornée au scénario (« voire plus longtemps » supprimé). Les trois rappels de consentement d''Éveiller le désir réduits à un."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_lilith_desir_sexe_plaisir_et_attachement_fertilite_chair', 'Fertilité & Chair', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"le corps comme puissance.","profil":null,"changements":"garde-fous de Fécondité divine ramenés à une phrase ; phrase Builder retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lilith_desir_sexe_plaisir_et_attachement_facette_fertilite_chair_corps_souverain', 'Corps souverain', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":null,"texte_court":"tu contrôles consciemment tes fonctions hormonales, reproductives et sexuelles.","texte_reference":"Contrôle conscient de ses propres fonctions hormonales, reproductives et sexuelles ; les altérations ordinaires de ce registre deviennent triviales.","lore":"Chez les Élus de Lilith, le corps n’est plus une mécanique opaque qu’il faudrait subir. Respiration, cycles hormonaux, désir, fertilité et réponse sexuelle peuvent être réglés consciemment avec la même intimité qu’un mouvement volontaire ; cette souveraineté ne change pas ce que l’Élu désire, elle lui rend simplement la maîtrise de sa propre chair.","groupe_actuel":"LILITH — Désir, Sexe, Plaisir et Attachement › Facette : Fertilité & Chair","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lilith_desir_sexe_plaisir_et_attachement_facette_fertilite_chair_chair_feconde', 'Chair féconde', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, contact","activation":"1 PA · contact · scène","texte_court":"moduler pour la scène une fonction hormonale ou reproductive d''une cible consentante, ou après opposition à sa Défense occulte. Ni guérison de toute maladie, ni handicap arbitraire.","texte_reference":"Pour 1 PA au contact, modulez pour la scène une fonction hormonale ou reproductive d’une cible consentante, ou après opposition à sa Défense occulte. Vous pouvez suspendre une perturbation ordinaire de ce registre, pas guérir n’importe quelle maladie ou infliger un handicap arbitraire.","lore":"La bénédiction de Lilith peut franchir la frontière de sa propre incarnation. Sous un contact accepté — ou après avoir imposé sa volonté à une âme qui résiste — l’Élu peut infléchir les cycles hormonaux et reproductifs d’un autre corps, accélérer, suspendre ou rétablir des fonctions que la biologie ordinaire traite comme involontaires.","groupe_actuel":"LILITH — Désir, Sexe, Plaisir et Attachement › Facette : Fertilité & Chair","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lilith_desir_sexe_plaisir_et_attachement_facette_fertilite_chair_fecondite_divine', 'Fécondité divine', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Rituel · 1 heure","texte_court":"un rituel d''une heure, après un examen réel, permet une restauration ou une modification reproductive durable et cohérente, convenue avec le MJ avant le rituel. Ni vie créée de rien, ni grossesse automatique ; la volonté des personnes est respectée.","texte_reference":"Un rituel d’une heure permet une restauration ou modification reproductive durable et biologiquement cohérente, définie avec le MJ à partir d’un examen réel. Il ne crée ni vie à partir de rien ni grossesse automatique et ne reproduit pas une signature unique de Duc.\n\nLa portée de la modification doit être convenue avant le rituel, dans le seul registre reproductif. La volonté des personnes concernées reste respectée ; aucun résultat biologique ou signature de Duc n’est inventé par le formulaire.","lore":"Pour Lilith, la fécondité n’est ni une récompense morale ni un simple hasard biologique : c’est une puissance de continuité. L’Élu peut rendre fertile ce qui pouvait l’être, préserver une conception fragile ou faire d’un corps vivant un terrain extraordinairement favorable à la naissance, sans créer une vie à partir de rien ni effacer la volonté des personnes concernées.","groupe_actuel":"LILITH — Désir, Sexe, Plaisir et Attachement › Facette : Fertilité & Chair","statut_regle":"correction","changements":"garde-fous de Fécondité divine ramenés à une phrase ; phrase Builder retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_lilith_desir_sexe_plaisir_et_attachement_attachement_sentiments', 'Attachement & Sentiments', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"lire et tordre les liens.","profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lilith_desir_sexe_plaisir_et_attachement_facette_attachement_sentiments_fil_du_c_ur', 'Fil du cœur', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"percevoir les attachements forts d''une cible : amour, haine passionnelle, dévotion, lien familial majeur.","texte_reference":"Percevoir les attachements émotionnels forts d’une cible : amour, haine passionnelle, dévotion ou lien familial majeur.","lore":"Les attachements forts apparaissent à l’Élu comme des tensions invisibles orientées vers des personnes, des causes ou des liens essentiels. Amour, haine passionnelle et dévotion n’ont pas la même couleur, mais tous tirent réellement sur le cœur.","groupe_actuel":"LILITH — Désir, Sexe, Plaisir et Attachement › Facette : Attachement & Sentiments","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lilith_desir_sexe_plaisir_et_attachement_facette_attachement_sentiments_attiser_apaiser', 'Attiser / Apaiser', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":"1 PA · scène","texte_court":"modifier un sentiment existant pour la scène. Apaiser une peur réduit d''un cran le Stress qui en vient ; attiser une émotion impose −3 aux actions qui la contrarient. Cible hostile : Défense occulte.","texte_reference":"Pour 1 PA, modifiez un sentiment existant pour la scène : apaiser une peur réduit d’un cran le Stress psychologique qui en découle, tandis qu’attiser une émotion impose −3 aux actions qui la contrarient directement. Une cible hostile oppose sa Défense occulte ; les minima de blessures et les autres causes de Stress demeurent.","lore":"Lilith ne crée pas ici une émotion étrangère : elle saisit celle qui existe déjà et en règle l’intensité. Une tendresse peut devenir brûlante, une rancœur s’éteindre presque entièrement, sans que la cible oublie pourquoi elle ressentait quelque chose.","groupe_actuel":"LILITH — Désir, Sexe, Plaisir et Attachement › Facette : Attachement & Sentiments","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lilith_desir_sexe_plaisir_et_attachement_facette_attachement_sentiments_c_ur_silencieux', 'Cœur silencieux', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 2 PA, 1/scène","activation":null,"texte_court":"Jet contre Défense occulte : une catégorie affective entière s''éteint chez la cible pour la scène (amour, tendresse, désir, attachement…).","texte_reference":"Défense occulte. Éteindre pour la scène une catégorie affective entière chez une cible : amour, tendresse, désir, attachement, etc.","lore":"Le Héraut coupe momentanément tout un registre affectif, laissant derrière lui une absence plus inquiétante qu’un simple calme. La personne sait encore ce qu’elle devrait aimer ou désirer, mais le sentiment correspondant ne répond plus.","groupe_actuel":"LILITH — Désir, Sexe, Plaisir et Attachement › Facette : Attachement & Sentiments","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_mammon_l_ineluctable', 'MAMMON — L''Inéluctable', NULL, '{"nature":"daemon","chemin":["MAMMON — L''Inéluctable"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_mammon_l_ineluctable_mort', 'Mort', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"voir la fin, la rapprocher, la donner.","profil":null,"changements":"texte de La Fin vient raccourci (condition répétée). Main du trépas gardée : DGT 9 au palier II est dans la ligne d''Écrasement (DGT 10). Ressort face à Corneille du trépas (Morrighan) : Mammon voit la mort qui vient, la Corneille voit les morts et les lieux marqués."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mammon_l_ineluctable_facette_mort_sens_du_dernier_souffle', 'Sens du dernier souffle', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"savoir aussitôt si un être visible est mourant, condamné à court terme ou vraiment mort.","texte_reference":"Percevoir immédiatement si un être visible est mourant, condamné à court terme ou déjà véritablement mort.","lore":"Mammon fait sentir la différence entre souffrir, agoniser et être déjà passé de l’autre côté. Le Daemon reconnaît l’approche de la fin comme d’autres reconnaissent une odeur, sans avoir besoin d’un diagnostic médical pour savoir qu’un souffle est presque le dernier.","groupe_actuel":"MAMMON — L’Inéluctable › Facette : Mort","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mammon_l_ineluctable_facette_mort_main_du_trepas', 'Main du trépas', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":null,"texte_court":"Jet contre Défense occulte, DGT 9, ignore les armures physiques.","texte_reference":"Attaque directe contre Défense occulte, DGT 9. Ignore les armures physiques : le pouvoir rapproche directement l’âme du vivant de sa propre fin.","lore":"Ce geste ne cherche pas à traverser une armure. Il rapproche directement une âme vivante de la frontière que Mammon représente ; métal, kevlar ou plaque céramique deviennent hors sujet face à une attaque qui s’adresse à la possibilité même de rester en vie.","groupe_actuel":"MAMMON — L’Inéluctable › Facette : Mort","statut_regle":"correction","changements":"texte de La Fin vient raccourci (condition répétée). Main du trépas gardée : DGT 9 au palier II est dans la ligne d''Écrasement (DGT 10). Ressort face à Corneille du trépas (Morrighan) : Mammon voit la mort qui vient, la Corneille voit les morts et les lieux marqués."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mammon_l_ineluctable_facette_mort_la_fin_vient', 'La Fin vient', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène","activation":"1 PA · 1/scène","texte_court":"contre une cible à 25 % de ses PV maximum ou moins : DGT 12. Ces PV ne se régénèrent pas avant la fin de la scène (les soins adaptés restent possibles). Si elle tombe à 0 PV ou moins, la stabiliser est plus dur d''un niveau jusqu''à la fin du round suivant.","texte_reference":"Une fois par scène, pour 1 PA, frappez à DGT 12 une cible à 25 % de ses PV maximum ou moins ; les PV perdus par cette frappe ne peuvent être régénérés avant la fin de la scène. Si elle tombe à 0 PV ou moins, la stabilisation garde son surcoût d’un niveau jusqu’à la fin du round suivant, sans empêcher les soins adaptés.\n\nLa condition de 25 % se calcule sur les PV maximum de la cible au moment de l’attaque. Seuls les PV effectivement perdus à cette frappe sont concernés ; les soins adaptés ne sont pas interdits.","lore":"Chez ceux qui vacillent déjà, Mammon rend la proximité de la mort presque matérielle. Le dernier coup paraît tirer la cible vers un seuil tout proche, et même ceux qui veulent la retenir sentent que la fin a commencé à réclamer son dû.","groupe_actuel":"MAMMON — L’Inéluctable › Facette : Mort","statut_regle":"correction","changements":"texte de La Fin vient raccourci (condition répétée). Main du trépas gardée : DGT 9 au palier II est dans la ligne d''Écrasement (DGT 10). Ressort face à Corneille du trépas (Morrighan) : Mammon voit la mort qui vient, la Corneille voit les morts et les lieux marqués."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_mammon_l_ineluctable_vieillesse', 'Vieillesse', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"le temps comme arme.","profil":null,"changements":"Années volées complétée (1 PA et Défense occulte, selon les précisions communes). Siècles en un souffle passe à 1/scène : c''était le seul palier III d''attaque répétable sans condition (Anéantissement est 1/scène ; Sentence exige une culpabilité établie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mammon_l_ineluctable_facette_vieillesse_poids_des_annees', 'Poids des années', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"Jet contre Défense occulte : −3 aux actions physiques jusqu''à la fin du prochain round.","texte_reference":"Défense occulte. −3 aux actions physiques d’une cible jusqu’à la fin du prochain round.","lore":"Mammon fait tomber d’un coup sur le corps la fatigue d’années qu’il n’a pas encore portées. Membres et souffle deviennent lourds, donnant à chaque geste l’impression d’être accompli après une vie entière de marche.","groupe_actuel":"MAMMON — L’Inéluctable › Facette : Vieillesse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mammon_l_ineluctable_facette_vieillesse_annees_volees', 'Années volées', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"Jet contre Défense occulte (sauf cible consentante) : pour la scène, la cible vieillit ou rajeunit en apparence et dans certaines fonctions biologiques.","texte_reference":"Vieillir ou rajeunir temporairement l’apparence et certaines fonctions biologiques d’une cible pendant une scène.","lore":"Le Héraut manipule l’âge comme une apparence biologique momentanément déplacée sur la ligne d’une vie. Peau, souffle et fonctions du corps avancent ou reculent ensemble, sans que l’histoire réellement vécue par la cible soit réécrite.","groupe_actuel":"MAMMON — L’Inéluctable › Facette : Vieillesse","statut_regle":"correction","changements":"Années volées complétée (1 PA et Défense occulte, selon les précisions communes). Siècles en un souffle passe à 1/scène : c''était le seul palier III d''attaque répétable sans condition (Anéantissement est 1/scène ; Sentence exige une culpabilité établie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mammon_l_ineluctable_facette_vieillesse_siecles_en_un_souffle', 'Siècles en un souffle', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, **1/scène**","activation":null,"texte_court":"vieillissement brutal. Jet contre Défense occulte, DGT 12 et conséquences physiques cohérentes. Ne tue jamais par simple déclaration.","texte_reference":"Vieillissement brutal : DGT 12 et conséquences physiques cohérentes. Ne tue jamais automatiquement par simple déclaration.","lore":"Le temps biologique s’emballe avec une brutalité visible. Ce qui aurait dû être une lente usure traverse la chair en quelques secondes, rappelant que l’Inéluctable ne promet jamais que les années arriveront une par une.","groupe_actuel":"MAMMON — L’Inéluctable › Facette : Vieillesse","statut_regle":"correction","changements":"Années volées complétée (1 PA et Défense occulte, selon les précisions communes). Siècles en un souffle passe à 1/scène : c''était le seul palier III d''attaque répétable sans condition (Anéantissement est 1/scène ; Sentence exige une culpabilité établie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_mammon_l_ineluctable_destin_delivrance', 'Destin & Délivrance', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"accomplir ce qui doit l''être.","profil":null,"changements":"« jet opposé à l''effet » précisé : contre sa Puissance. Écart de source : Dernière destination 1/scène sur le site, 1/scénario dans le catalogue (on garde le site)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mammon_l_ineluctable_facette_destin_delivrance_accepter_l_ineluctable', 'Accepter l''inéluctable', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"+3 pour résister à la peur, à la douleur ou à un effet qui veut t''empêcher d''accomplir une action que tu sais nécessaire.","texte_reference":"+3 pour résister à peur, douleur ou effet visant à empêcher le Daemon d’accomplir une action qu’il sait nécessaire.","lore":"Mammon enseigne une forme de paix qui n’a rien de douce : reconnaître ce qui doit être traversé et avancer malgré le prix. Peur et douleur restent réelles, mais elles cessent d’être des arguments suffisants pour détourner l’Élu de la nécessité.","groupe_actuel":"MAMMON — L’Inéluctable › Facette : Destin & Délivrance","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mammon_l_ineluctable_facette_destin_delivrance_fin_des_souffrances', 'Fin des souffrances', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 2 PA","activation":null,"texte_court":"mettre fin à une malédiction, une possession, une douleur surnaturelle ou un effet persistant qui est une souffrance maintenue : Jet de pouvoir contre sa Puissance.","texte_reference":"Tenter de mettre fin à une malédiction, possession, douleur surnaturelle ou effet persistant dont la logique est réellement une souffrance maintenue. Jet opposé à l’effet.","lore":"L’Inéluctable sait aussi qu’une souffrance entretenue artificiellement doit avoir une fin. Le Héraut cherche le point où malédiction, possession ou douleur surnaturelle s’accroche encore au monde et tente d’y imposer la délivrance.","groupe_actuel":"MAMMON — L’Inéluctable › Facette : Destin & Délivrance","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mammon_l_ineluctable_facette_destin_delivrance_derniere_destination', 'Dernière destination', NULL, '{"nature":"daemon","cout":3,"cout_actuel":2,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1/scène","activation":"1 PA · 1/scène","texte_court":"quand une issue précise est engagée, tu perçois le dernier obstacle réel et une action praticable pour le lever ; +3 au premier test pour l''accomplir.","texte_reference":"Une fois par scène, lorsqu’une issue précise est déjà engagée, percevez le dernier obstacle réel qui l’empêche encore et une action immédiatement praticable pour le lever. Votre premier test pour accomplir cette action gagne +3 ; le talent ne choisit pas l’issue à votre place et ne prédit pas tout l’avenir.","lore":"Quand une situation a déjà pris une direction, le Héraut perçoit quelle action la rapprocherait le plus sûrement de son terme. Il ne voit pas l’avenir entier ; il reconnaît la pente sur laquelle les événements ont commencé à glisser.","groupe_actuel":"MAMMON — L’Inéluctable › Facette : Destin & Délivrance","statut_regle":"correction","changements":"Coût 2 → 3. « jet opposé à l''effet » précisé : contre sa Puissance. Écart de source : Dernière destination 1/scène sur le site, 1/scénario dans le catalogue (on garde le site)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_mephisto_l_occulte_la_parole_et_le_hasard', 'MÉPHISTO — L''Occulte, la Parole et le Hasard', NULL, '{"nature":"daemon","chemin":["MÉPHISTO — L''Occulte, la Parole et le Hasard"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_mephisto_l_occulte_la_parole_et_le_hasard_magie', 'Magie', NULL, '{"nature":"daemon","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":"le Spectre grandit, puis se dédouble.","profil":null,"changements":"usage Significatif limité à 1/scène. C''est le ressort propre du Daemon (une cadence, comme ses Facettes), à la place d''une Tension qu''il n''a pas. Voir question 3. Phrases Builder retirées. Pas de contradiction de plafond : l''Empreinte donne Initiale / Mineure, les paliers montent jusqu''à Affinée / Significative."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mephisto_l_occulte_la_parole_et_le_hasard_facette_magie_spectre_affine', 'Spectre affiné', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":"Progression · par Spectre","texte_court":"ton Spectre passe en Maîtrise Affinée (précision, formes complexes, division simple).","texte_reference":"Choisissez une Affinité spectrale possédée : elle passe à Maîtrise Affinée, autorisant précision, formes complexes et division simple d’un effet. Ce développement se paie par Affinité, sans ouvrir la progression d’un véritable Mage.\n\nLe premier achat canonique améliore le premier Spectre ; le second exemplaire porte exclusivement sur le second Spectre et coûte également 1 PTV. Aucun bonus d’Attribut ou de Maîtrise spirituelle n’est accordé.","lore":"Méphisto ouvre au Daemon une compréhension plus précise du Spectre de Mageius. Les phénomènes magiques cessent d’être seulement des forces à convoquer : ils deviennent des structures dont les nuances peuvent être choisies et contrôlées avec une finesse supérieure.","groupe_actuel":"MÉPHISTO — L’Occulte, la Parole et le Hasard › Facette : Magie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mephisto_l_occulte_la_parole_et_le_hasard_facette_magie_spectre_amplifie', 'Spectre amplifié', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":"Progression · par Spectre","texte_court":"ton Spectre atteint l''Amplitude Significative ; ses usages Mineurs baissent leur Difficulté d''un niveau (minimum 12). **Un seul usage Significatif par scène** : la Cour prête, elle ne donne pas. Toujours sans Tension ni Revers.","texte_reference":"Choisissez une Affinité spectrale possédée : elle atteint l’Amplitude Significative et ses effets Mineurs gagnent un niveau de réduction de Difficulté intrinsèque. Les PA, portées et Défenses normales restent applicables ; le Spectre ne produit toujours ni Tension ni Revers.\n\nLe premier achat canonique améliore le premier Spectre ; développer le second coûte également 2 PTV. La Difficulté intrinsèque ne descend pas sous 12 ; ni la Défense adverse ni les PA ne diminuent.","lore":"Après la finesse vient l’ampleur. Le même langage spectral peut désormais porter une manifestation assez vaste pour changer réellement la scène, preuve que l’Occulte de Méphisto ne sépare jamais connaissance et capacité à imposer cette connaissance au monde.","groupe_actuel":"MÉPHISTO — L’Occulte, la Parole et le Hasard › Facette : Magie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mephisto_l_occulte_la_parole_et_le_hasard_facette_magie_polyphonie_occulte', 'Polyphonie occulte', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Progression · second Spectre","texte_court":"un second Spectre, d''une autre Affinité, en Initiale / Mineure. Il progresse à part (Affiné 1 PTV, Amplifié 2 PTV), jamais au-delà d''Affinée / Significative.","texte_reference":"Choisissez une seconde Affinité spectrale différente, qui commence en Initiale / Mineure. Ses paliers se développent séparément par Spectre affiné et Spectre amplifié, sans jamais dépasser Affinée / Significative.\n\nLes deux Affinités doivent être distinctes et choisies parmi les quinze domaines du moteur magique. Aucun Écho, Œuvre, Volonté supérieure ou accès à la Roue des Mageius n’est accordé. Une ancienne acquisition reste conservée et payée lorsque son choix reste à compléter.","lore":"L’Élu apprend à écouter deux couleurs de Magie sans les confondre. Une seconde Affinité vient compléter la première comme une voix supplémentaire dans un accord, encore limitée mais déjà assez réelle pour ouvrir des pratiques jusque-là étrangères.","groupe_actuel":"MÉPHISTO — L’Occulte, la Parole et le Hasard › Facette : Magie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_mephisto_l_occulte_la_parole_et_le_hasard_parole_chant', 'Parole & Chant', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"une voix qui porte et qui arrête.","profil":null,"changements":"phrase répétée de Verbe historique retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mephisto_l_occulte_la_parole_et_le_hasard_facette_parole_chant_voix_qui_porte', 'Voix qui porte', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"toute cible choisie t''entend clairement jusqu''à 100 m, même dans le vacarme.","texte_reference":"La voix peut être entendue clairement par toute cible choisie jusqu’à environ 100 m, même au milieu d’un vacarme.","lore":"La voix choisit ses auditeurs plutôt que de se perdre dans la distance. Elle traverse vacarme et espace sans devenir nécessairement plus forte pour les autres, comme si Méphisto avait tendu un fil sonore directement jusqu’à chaque oreille désignée.","groupe_actuel":"MÉPHISTO — L’Occulte, la Parole et le Hasard › Facette : Parole & Chant","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mephisto_l_occulte_la_parole_et_le_hasard_facette_parole_chant_mot_irresistible', 'Mot irrésistible', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, Réaction 1 PA, 1/scène","activation":"Réaction · 1 PA · 1/scène","texte_court":"avant qu''une action se résolve, une phrase compréhensible : Charisme + Diplomatie contre Défense occulte. L''action est interrompue ; l''interlocuteur garde son PA et peut agir autrement.","texte_reference":"Une fois par scène, pour 1 PA en Réaction avant sa résolution, adressez une phrase compréhensible à un interlocuteur et opposez Charisme + Diplomatie à sa Défense occulte pour interrompre son action. Il conserve son PA et peut choisir une autre action ; aucun ordre suicidaire ni domination durable n’est imposé.","lore":"Une phrase brève reçoit une résonance qui dépasse sa simple éloquence. Les mots arrivent avec l’impression qu’ils étaient ceux qu’il fallait entendre à cet instant, poussant l’auditeur vers la réaction que leur intention contenait déjà.","groupe_actuel":"MÉPHISTO — L’Occulte, la Parole et le Hasard › Facette : Parole & Chant","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mephisto_l_occulte_la_parole_et_le_hasard_facette_parole_chant_verbe_historique', 'Verbe historique', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 3 PA, 1/scène","activation":"3 PA · 1/scène","texte_court":"un discours, préparable sur plusieurs rounds. Les alliés qui l''entendent gagnent +3 à une catégorie d''action annoncée avant le test, jusqu''à la fin de la scène. Pas de cumul avec un soutien équivalent.","texte_reference":"Pour 3 PA de discours, une fois par scène, vos alliés qui l’entendent gagnent +3 sur une catégorie d’action précise et annoncée jusqu’à la fin de la scène. Le discours peut être préparé sur des rounds consécutifs ; il ne fournit aucune compétence et ne cumule pas un soutien équivalent.\n\nLe discours s’adresse aux alliés capables de l’entendre ; la catégorie d’action est fixée avant le test, pas après les résultats.","lore":"Le discours s’installe dans la mémoire de ceux qui l’écoutent et donne un sens commun à leurs actes suivants. Il ne leur fournit aucun savoir nouveau ; il transforme plutôt une foule d’intentions séparées en récit partagé capable de soutenir l’action.","groupe_actuel":"MÉPHISTO — L’Occulte, la Parole et le Hasard › Facette : Parole & Chant","statut_regle":"correction","changements":"phrase répétée de Verbe historique retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_mephisto_l_occulte_la_parole_et_le_hasard_fortune_illusion', 'Fortune & Illusion', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"tricher avec le hasard et les sens.","profil":null,"changements":"accès SR/R ajouté à Fortune volée (absent) ; deux phrases redondantes retirées."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mephisto_l_occulte_la_parole_et_le_hasard_facette_fortune_illusion_bonne_etoile', 'Bonne étoile', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1/scène","activation":null,"texte_court":"relance ton d10e et garde le second résultat.","texte_reference":"Relancer son d10e et conserver le second résultat.","lore":"Méphisto accorde parfois une seconde lecture du hasard. L’instant qui semblait fixé se déplie encore une fois, comme si la pièce avait rebondi sur sa tranche avant de révéler enfin de quel côté elle choisissait de tomber.","groupe_actuel":"MÉPHISTO — L’Occulte, la Parole et le Hasard › Facette : Fortune & Illusion","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mephisto_l_occulte_la_parole_et_le_hasard_facette_fortune_illusion_mensonge_du_monde', 'Mensonge du monde', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":"1 PA · rayon 3 m à 20 m · scène","texte_court":"illusion multisensorielle de 3 m à 20 m, pour la scène. Extérieure (les capteurs la voient, la Perception la démasque) ou mentale (Défense occulte, aucune matière).","texte_reference":"Pour 1 PA, créez pour la scène une illusion multisensorielle dans une zone de 3 m de rayon à 20 m, en déclarant si elle est extérieure ou directement mentale. Une illusion extérieure est perceptible par les capteurs adaptés et se démasque par Perception ; une illusion mentale affronte la Défense occulte et ne produit aucune matière réelle.","lore":"Méphisto donne au faux assez de cohérence pour occuper les sens. Son, volume, couleur et présence s’accordent en une scène qui n’existe pas, mais dont les détails sont suffisamment liés pour tromper tant qu’aucune perception plus profonde ne la déchire.","groupe_actuel":"MÉPHISTO — L’Occulte, la Parole et le Hasard › Facette : Fortune & Illusion","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'mephisto_l_occulte_la_parole_et_le_hasard_facette_fortune_illusion_fortune_volee', 'Fortune volée', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, Réaction 1 PA, 1/scène","activation":"Réaction · 1 PA · 1/scène","texte_court":"après le jet réussi d''un adversaire visible, avant ses conséquences : il relance son d10e et garde le second résultat. Tu gagnes +3 à ton prochain test avant la fin du round suivant.","texte_reference":"Une fois par scène, pour 1 PA en Réaction après un jet adverse réussi mais avant ses conséquences, imposez à un adversaire visible de relancer son d10e et de conserver le second résultat. Vous gagnez +3 à votre prochain test avant la fin du round suivant, sans deuxième relance de talent sur le même test.\n\nLa réaction vise un jet que l’adversaire vient de réussir. Le second résultat est conservé même s’il est meilleur ; les conséquences du premier résultat ne sont pas appliquées avant la relance.","lore":"Le Héraut dérobe à l’adversaire l’assurance d’un heureux hasard. La réussite vacille et doit se rejouer, tandis qu’une part de cette chance arrachée reste un instant disponible pour le prochain geste de l’Élu.","groupe_actuel":"MÉPHISTO — L’Occulte, la Parole et le Hasard › Facette : Fortune & Illusion","statut_regle":"correction","changements":"accès SR/R ajouté à Fortune volée (absent) ; deux phrases redondantes retirées."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_satan_le_juge', 'SATAN — Le Juge', NULL, '{"nature":"daemon","chemin":["SATAN — Le Juge"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_satan_le_juge_sentence', 'Sentence', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"frapper le coupable, et lui seul.","profil":null,"changements":"Défense occulte de Sentence écrite (précisions communes)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'satan_le_juge_facette_sentence_poids_de_la_faute', 'Poids de la faute', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"Jet contre Défense occulte, DGT 7. Aucun effet sur une cible innocente de l''acte jugé.","texte_reference":"Attaque contre Défense occulte, DGT 7. Aucun effet sur une cible réellement innocente de l’acte pour lequel elle est jugée.","lore":"Satan ne frappe pas parce qu’une cible est détestée, mais parce qu’un acte peut lui être imputé. La sentence trouve d’autant mieux sa prise que la culpabilité est réelle ; face à un innocent de l’accusation formulée, le pouvoir n’a simplement rien à juger.","groupe_actuel":"SATAN — Le Juge › Facette : Sentence","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'satan_le_juge_facette_sentence_chaines_du_coupable', 'Chaînes du coupable', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":"1 PA · scène","texte_court":"culpabilité établie pour un acte précis : Jet contre Défense occulte, la cible est immobilisée jusqu''à la fin de la scène. Se libérer : 1 PA et Volonté + Force Mentale contre le résultat initial. Accusation inventée : aucun effet.","texte_reference":"Pour 1 PA, après avoir établi la culpabilité pour un acte précis, opposez votre Jet divin à la Défense occulte pour immobiliser la cible jusqu’à la fin de la scène. Se libérer coûte 1 PA et Volonté + Force Mentale contre le résultat initial ; une accusation inventée ne donne aucun effet.","lore":"Le jugement devient matière. Plus la responsabilité est lourde et établie, plus les chaînes ont de raison d’exister ; elles immobilisent le condamné comme si sa propre faute fournissait le poids nécessaire à sa détention.","groupe_actuel":"SATAN — Le Juge › Facette : Sentence","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'satan_le_juge_facette_sentence_sentence', 'Sentence', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA","activation":null,"texte_court":"contre une cible dont la culpabilité est établie : Jet contre Défense occulte, DGT 12, ignore 3 Protection surnaturelle. Nul contre un innocent.","texte_reference":"DGT 12 contre une cible dont la culpabilité a été établie ; ignore 3 Protection surnaturelle. Toujours nul contre un innocent.","lore":"Une culpabilité établie donne à la sentence une prise que l’innocence refuse absolument. Le châtiment cherche moins la chair que la faute reconnue derrière elle, et se dissipe sans effet lorsqu’aucun acte ne justifie réellement le jugement.","groupe_actuel":"SATAN — Le Juge › Facette : Sentence","statut_regle":"correction","changements":"Défense occulte de Sentence écrite (précisions communes)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_satan_le_juge_ordre_paix', 'Ordre & Paix', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"imposer la paix, à tous.","profil":null,"changements":"Cessez reformulé (le jet est celui du Daemon) ; les cinq conditions de Loi du Juge ramenées à une phrase."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'satan_le_juge_facette_ordre_paix_cessez', 'Cessez', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"à voix haute, Jet contre la Défense occulte d''une cible qui t''entend : si elle échoue, elle ne peut pas poursuivre aussitôt son action violente.","texte_reference":"Une cible doit réussir Défense occulte pour poursuivre immédiatement une action violente après l’injonction.","lore":"Un seul mot du Juge interrompt l’élan de violence et oblige son auteur à reconnaître qu’il s’apprête à poursuivre. Cette hésitation n’est pas la paix elle-même, mais elle crée l’espace minuscule où une volonté peut encore choisir de ne pas frapper.","groupe_actuel":"SATAN — Le Juge › Facette : Ordre & Paix","statut_regle":"correction","changements":"Cessez reformulé (le jet est celui du Daemon) ; les cinq conditions de Loi du Juge ramenées à une phrase."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'satan_le_juge_facette_ordre_paix_treve', 'Trêve', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 2 PA","activation":"2 PA · rayon 10 m · scène","texte_court":"Trêve de 10 m pour la scène. Qui veut attaquer doit réussir Volonté + Force Mentale contre 15 à chaque tentative ; en échec, l''attaque ne part pas et le PA est perdu. Les Défenses restent possibles pour tous.","texte_reference":"Pour 2 PA, établissez une Trêve de 10 m de rayon pour la scène : quiconque veut engager une attaque doit réussir Volonté + Force Mentale 15, une fois par tentative payée. En échec l’attaque ne part pas et le PA est consommé ; les Défenses restent toujours possibles, pour tous les camps.","lore":"La trêve n’efface pas le conflit ; elle suspend l’initiative meurtrière. Dans l’espace marqué par le Juge, recommencer volontairement les hostilités exige de franchir une résistance intérieure que la simple colère ne suffit plus toujours à vaincre.","groupe_actuel":"SATAN — Le Juge › Facette : Ordre & Paix","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'satan_le_juge_facette_ordre_paix_loi_du_juge', 'Loi du Juge', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 2 PA","activation":"2 PA · rayon 10 m · scène","texte_court":"annonce pour la scène une règle de paix claire, publique et réalisable, valable pour tous à 10 m, toi compris. Violation volontaire : résistance occulte contre ton jet initial, sinon 3 PV irréductibles (une sanction par personne et par round). Ne crée pas la culpabilité des talents de Sentence.","texte_reference":"Pour 2 PA, annoncez pour la scène une règle de paix claire, réalisable et applicable à tous dans un rayon de 10 m. Une violation volontaire entraîne 3 PV irréductibles après échec d’une résistance occulte contre le Jet divin initial, au maximum une sanction par personne et par round, sans créer de culpabilité morale.\n\nLa règle doit être publique, compréhensible, raisonnablement réalisable, non suicidaire et destinée à rétablir l’ordre ou la paix. Elle vaut également pour le Daemon et ses alliés ; une convention violée ne fabrique pas la culpabilité nécessaire aux Talents de Sentence.","lore":"Satan énonce ici une règle publique dont le Juge accepte lui-même le poids. Tant qu’elle reste raisonnable et destinée à restaurer l’ordre, la scène entière paraît savoir qui la respecte et qui décide consciemment de la briser.","groupe_actuel":"SATAN — Le Juge › Facette : Ordre & Paix","statut_regle":"correction","changements":"Cessez reformulé (le jet est celui du Daemon) ; les cinq conditions de Loi du Juge ramenées à une phrase."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_satan_le_juge_vengeance', 'Vengeance', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"la dette se paie.","profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'satan_le_juge_facette_vengeance_dette', 'Dette', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, gratuit, 1/round","activation":"Gratuit · 1/round","texte_court":"quand un ennemi blesse volontairement toi ou un protégé, marque-le : +3 à ton prochain jet contre lui dans la scène. Une seule dette active.","texte_reference":"Une fois par round, lorsqu’un ennemi blesse volontairement le Daemon ou un protégé, marquez-le gratuitement pour gagner +3 à votre prochain jet contre lui dans la scène. Une seule dette est active et le bonus ne se cumule pas avec une représaille équivalente.","lore":"Un dommage volontaire inscrit une dette visible pour le Juge. Jusqu’à ce qu’elle soit réclamée ou que l’instant passe, l’agresseur porte la marque de ce qu’il vient de faire et devient plus facile à atteindre par celui qu’il a lésé.","groupe_actuel":"SATAN — Le Juge › Facette : Vengeance","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'satan_le_juge_facette_vengeance_retour_des_actes', 'Retour des actes', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, Réaction 1 PA","activation":"Réaction · 1 PA","texte_court":"après avoir subi un effet hostile : Jet contre la Défense occulte de son auteur ; réussite : −3 à une famille d''actions cohérente jusqu''à la fin de son prochain round.","texte_reference":"Pour 1 PA en Réaction après avoir subi un effet hostile, opposez votre Jet divin à la Défense occulte de son auteur. En réussite, le contrecoup lui impose −3 à une famille d’actions cohérente avec ce que vous avez subi jusqu’à la fin de son prochain round, sans copier son pouvoir ni annuler votre propre dommage.","lore":"L’acte hostile laisse derrière lui une conséquence que Satan peut renvoyer vers son auteur. Ce n’est pas une copie parfaite du coup : plutôt son principe réduit — douleur, recul ou épuisement — rendu à celui qui l’avait imposé.","groupe_actuel":"SATAN — Le Juge › Facette : Vengeance","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'satan_le_juge_facette_vengeance_il_pour_il', 'Œil pour œil', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène","activation":"1 PA · 1/scène","texte_court":"contre l''auteur d''une attaque dont tu as constaté les dommages dans la scène : Jet contre Défense occulte ; il perd autant de PV que sa victime (maximum 12, sans marge).","texte_reference":"Une fois par scène, pour 1 PA, opposez votre Jet divin à la Défense occulte de l’auteur d’une attaque dont vous avez constaté les dommages dans cette scène. En réussite, il perd autant de PV que sa victime en avait réellement perdu, maximum 12 et sans ajout de marge ; aucun cumul de plusieurs attaques n’est permis.","lore":"La vengeance prend la forme la plus littérale de la balance. Le Juge mesure le dommage réellement subi puis présente la même dette à son auteur, sans permettre que la réparation devienne prétexte à une punition infiniment supérieure.","groupe_actuel":"SATAN — Le Juge › Facette : Vengeance","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_lucifer_le_soleil_dechu', 'LUCIFER — Le Soleil déchu', NULL, '{"nature":"daemon","chemin":["LUCIFER — Le Soleil déchu"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_lucifer_le_soleil_dechu_soleil', 'Soleil', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"la lumière qui brûle les créatures de la nuit.","profil":null,"changements":"non-cumul de la Radiance écrit une fois (il l''était trois fois)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lucifer_le_soleil_dechu_facette_soleil_trait_solaire', 'Trait solaire', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":null,"texte_court":"attaque, Défense physique, DGT 7 (+3 de Radiance contre les vulnérables).","texte_reference":"Attaque physique DGT 7 ; +3 DGT contre créature intrinsèquement vulnérable au solaire.","lore":"Lucifer concentre sa mémoire du Soleil en une violence blanche et immédiate. Pour la plupart des créatures c’est déjà une attaque divine ; pour celles dont la nature porte une faiblesse solaire, c’est la rencontre brutale avec quelque chose que leur corps reconnaît comme un ennemi primordial.","groupe_actuel":"LUCIFER — Le Soleil déchu › Facette : Soleil","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lucifer_le_soleil_dechu_facette_soleil_halo_du_jour', 'Halo du jour', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":"1 PA · rayon 10 m · scène","texte_court":"rayonnement de 10 m pour la scène. Les créatures vulnérables au solaire y ont −3 à leurs actions ; les ténèbres surnaturelles mineures dont tu bats la Puissance reculent. Pas de dégâts périodiques.","texte_reference":"Pour 1 PA, rayonnez sur 10 m pour la scène : les créatures réellement vulnérables au solaire y subissent −3 à leurs actions. Les ténèbres surnaturelles mineures sont repoussées après opposition à leur Puissance ; aucun dégât périodique gratuit n’est ajouté.","lore":"Le Daemon ne lance plus seulement de la lumière : il installe autour de lui un petit territoire de jour. Les ténèbres surnaturelles mineures reculent et les prédateurs nocturnes doivent agir sous un ciel qui, pendant quelques instants, ne leur appartient plus.","groupe_actuel":"LUCIFER — Le Soleil déchu › Facette : Soleil","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lucifer_le_soleil_dechu_facette_soleil_aube_implacable', 'Aube implacable', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 3 PA, 1/scène","activation":"3 PA · 1/scène · rayon 15 m","texte_court":"aube de 15 m. Un jet contre chaque Défense physique : DGT 12 aux cibles hostiles vulnérables au solaire, +3 de Radiance une seule fois. Dissipe les ténèbres temporaires dont tu bats la Puissance. Être habitué à la nuit ne rend pas vulnérable.","texte_reference":"Pour 3 PA, une fois par scène, déployez une aube de 15 m de rayon : un Jet divin contre chaque Défense, DGT 12 de base aux cibles hostiles vulnérables au solaire, plus le seul +3 de Radiance originelle. Le même résultat dissipe les ténèbres temporaires dont il surpasse la Puissance, sans seconde vague de dégâts.\n\nLe rayonnement physique affronte la Défense physique ; le +3 de Radiance originelle n’est compté qu’une fois, jamais une fois par libellé. Les êtres seulement habitués à la nuit ne sont pas des cibles vulnérables au solaire.","lore":"Une véritable aube se lève autour de l’Élu, même loin de l’horizon. Les ténèbres surnaturelles reculent devant cette présence, tandis que les créatures pour lesquelles le soleil est une menace retrouvent soudain la vieille raison de craindre le jour.","groupe_actuel":"LUCIFER — Le Soleil déchu › Facette : Soleil","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_lucifer_le_soleil_dechu_cycle_vie', 'Cycle & Vie', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"le matin revient.","profil":null,"changements":"Refus du crépuscule entre dans le plafond de survie. Renaissance (Lucifer, restaurer ce qui vient de se perdre) et Reconstruction (Belzébuth, rebâtir un organe) gardent chacune leur Divinité : pas de fusion."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lucifer_le_soleil_dechu_facette_cycle_vie_premier_matin', 'Premier matin', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"retirer un état simple de fatigue, de choc ou d''étourdissement, à toi ou à un allié.","texte_reference":"Retirer un état simple de fatigue, choc ou étourdissement à soi-même ou un allié.","lore":"Un bref renouveau parcourt le corps comme le premier souffle après une nuit trop longue. Fatigue, choc ou étourdissement perdent leur emprise immédiate, non par oubli de la blessure mais parce que le cycle repart.","groupe_actuel":"LUCIFER — Le Soleil déchu › Facette : Cycle & Vie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lucifer_le_soleil_dechu_facette_cycle_vie_renaissance', 'Renaissance', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 2 PA","activation":null,"texte_court":"soigner 3 + DR PV ou restaurer une fonction biologique récemment perdue. Pas de nouveau soin de cette source sur la même cible avant la fin de la scène ou un vrai repos.","texte_reference":"Soigner 3 + DR PV ou restaurer une fonction biologique récemment perdue. Une même source surnaturelle de guérison ne peut restaurer des PV à nouveau avant la fin de la scène ou un vrai repos.","lore":"La lumière solaire réveille dans la chair le souvenir de son état vivant. Une fonction récemment perdue peut reprendre ou une blessure se refermer, comme si l’organisme recevait l’ordre de recommencer plutôt que de poursuivre son déclin.","groupe_actuel":"LUCIFER — Le Soleil déchu › Facette : Cycle & Vie","statut_regle":"correction","changements":"Refus du crépuscule entre dans le plafond de survie. Renaissance (Lucifer, restaurer ce qui vient de se perdre) et Reconstruction (Belzébuth, rebâtir un organe) gardent chacune leur Divinité : pas de fusion."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lucifer_le_soleil_dechu_facette_cycle_vie_refus_du_crepuscule', 'Refus du crépuscule', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1/scénario","activation":null,"texte_court":"une cible visible vient d''atteindre son seuil de Mort : elle revient à 0 PV, Agonisante mais vivante. Pas si l''âme est partie ou le corps irrécupérable.","texte_reference":"Lorsqu’une cible visible vient juste d’atteindre son seuil de Mort, la ramener à 0 PV, Agonisante mais vivante. Ne fonctionne pas si l’âme est déjà partie ou le corps irrécupérable.","lore":"Au seuil précis où la vie devrait basculer, Lucifer retient encore l’aube du côté des vivants. Le corps reste brisé et en danger, mais l’âme qui n’est pas encore partie reçoit une dernière possibilité de demeurer.","groupe_actuel":"LUCIFER — Le Soleil déchu › Facette : Cycle & Vie","statut_regle":"correction","changements":"Refus du crépuscule entre dans le plafond de survie. Renaissance (Lucifer, restaurer ce qui vient de se perdre) et Reconstruction (Belzébuth, rebâtir un organe) gardent chacune leur Divinité : pas de fusion."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_lucifer_le_soleil_dechu_courage', 'Courage', NULL, '{"nature":"daemon","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":"un courage qui s''étend : toi, tes proches, ta troupe.","profil":null,"changements":"forme progression ; Cœur solaire n''est plus un doublon de Rayonner, il en est le premier palier."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lucifer_le_soleil_dechu_facette_courage_c_ur_solaire', 'Cœur solaire', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"+3 contre la peur et l''intimidation surnaturelle.","texte_reference":"+3 contre peur et intimidation surnaturelle.","lore":"Une chaleur stable demeure derrière le sternum lorsque la peur cherche à prendre toute la place. Elle n’abolit ni prudence ni instinct de survie ; elle rappelle simplement au Héraut qu’il peut choisir son geste même sous la menace.","groupe_actuel":"LUCIFER — Le Soleil déchu › Facette : Courage","statut_regle":"correction","changements":"forme progression ; Cœur solaire n''est plus un doublon de Rayonner, il en est le premier palier."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lucifer_le_soleil_dechu_facette_courage_rayonner', 'Rayonner', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"les alliés proches gagnent aussi ce +3 et peuvent refaire aussitôt un test pour sortir d''une terreur.","texte_reference":"Les alliés proches gagnent +3 contre peur et peuvent refaire immédiatement un test permettant de sortir d’un effet de terreur.","lore":"Le Héraut se dresse comme un point de jour au milieu de la panique. Ceux qui l’entourent retrouvent assez de clarté pour reprendre prise sur eux-mêmes et regarder de nouveau la source de leur peur.","groupe_actuel":"LUCIFER — Le Soleil déchu › Facette : Courage","statut_regle":"correction","changements":"forme progression ; Cœur solaire n''est plus un doublon de Rayonner, il en est le premier palier."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'lucifer_le_soleil_dechu_facette_courage_gloire_du_jour', 'Gloire du Jour', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène","activation":"1 PA · 1/scène · 5 alliés à 10 m","texte_court":"jusqu''à cinq alliés à 10 m ignorent pour la scène les effets de Tendu et Paniqué venus de la seule peur. Blessures et liberté de fuir inchangées.","texte_reference":"Une fois par scène, pour 1 PA, jusqu’à cinq alliés à 10 m ignorent pour la scène les conséquences de Tendu et Paniqué provenant de la seule peur. Les blessures, les autres contraintes et leur liberté de battre en retraite restent inchangées.","lore":"Le courage de Lucifer devient contagieux pendant quelques secondes. Les alliés voient encore le danger, mais la présence solaire autour d’eux empêche la terreur extérieure de décider à leur place s’ils doivent tenir ou partir.","groupe_actuel":"LUCIFER — Le Soleil déchu › Facette : Courage","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_belzebuth_la_vie_sans_jugement_moral', 'BELZÉBUTH — La Vie sans jugement moral', NULL, '{"nature":"daemon","chemin":["BELZÉBUTH — La Vie sans jugement moral"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_belzebuth_la_vie_sans_jugement_moral_regeneration', 'Régénération', NULL, '{"nature":"daemon","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":"un soin qui grandit.","profil":null,"changements":"saturation écrite une fois."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belzebuth_la_vie_sans_jugement_moral_facette_regeneration_seve_vitale', 'Sève vitale', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, toi ou contact","activation":null,"texte_court":"récupérer 1 + DR PV.","texte_reference":"Récupérer 1 + DR PV sur soi ou au contact. Une même source de guérison surnaturelle ne peut restaurer à nouveau des PV à la même cible avant la fin de la scène ou un vrai repos.","lore":"Belzébuth ne soigne pas par compassion abstraite mais parce que la Vie cherche à continuer. Sous la main du Héraut, tissus et fonctions reprennent assez vite pour refermer une partie de la blessure, jusqu’à ce que la saturation impose enfin une limite à cette insistance.","groupe_actuel":"BELZÉBUTH — La Vie sans jugement moral › Facette : Régénération","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belzebuth_la_vie_sans_jugement_moral_facette_regeneration_reconstruction', 'Reconstruction', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 2 PA","activation":null,"texte_court":"restaurer un organe, une fracture ou un tissu lourdement endommagé, ou soigner 3 + DR PV.","texte_reference":"Restaurer organe, fracture ou tissu lourdement endommagé ; peut aussi permettre une récupération 3 + DR dans les limites de saturation.","lore":"Là où Sève vitale maintient, Reconstruction rebâtit. Fracture, organe ou tissu détruit redevient un problème de croissance dirigée : la Vie remonte son propre plan et force le corps à reprendre une architecture qu’il n’aurait jamais pu restaurer seul.","groupe_actuel":"BELZÉBUTH — La Vie sans jugement moral › Facette : Régénération","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belzebuth_la_vie_sans_jugement_moral_facette_regeneration_printemps', 'Printemps', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène","activation":"1 PA · 1/scène · 3 alliés à 10 m","texte_court":"jusqu''à trois alliés à 10 m récupèrent chacun 3 + DR PV, sur un seul jet.","texte_reference":"Une fois par scène, pour 1 PA, jusqu’à trois alliés à 10 m récupèrent chacun 3 + DR PV à partir du même Jet divin. La saturation commune aux soins de cette source demeure applicable à chacun.\n\nSève vitale, Reconstruction et Printemps d’un même Élu partagent la saturation de guérison sur une cible. La Faveur Deuxième printemps de Perséphone conserve son exception écrite : jusqu’à 2 PV une fois par scénario.","lore":"La régénération prend une ampleur saisonnière. Autour du Héraut, plusieurs corps blessés reçoivent le même signal de reprise, comme si un printemps invisible avait ordonné aux tissus de recommencer à croître ensemble.","groupe_actuel":"BELZÉBUTH — La Vie sans jugement moral › Facette : Régénération","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_belzebuth_la_vie_sans_jugement_moral_nature_evolution', 'Nature & Évolution', NULL, '{"nature":"daemon","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":"le corps s''adapte.","profil":null,"changements":"répertoire décrit une fois (il l''était deux)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belzebuth_la_vie_sans_jugement_moral_facette_nature_evolution_adaptation', 'Adaptation', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":null,"texte_court":"pour la scène, une adaptation simple sur toi : branchies, vision nocturne, résistance au froid, griffes DGT 3…","texte_reference":"Pour la scène, produire une adaptation simple sur soi : branchies, vision nocturne, résistance au froid, griffes DGT 3, etc.","lore":"La chair improvise une réponse que l’évolution ordinaire aurait peut-être mise des générations à sélectionner. Poumons, yeux, peau ou armes naturelles se réorganisent pour le besoin immédiat, puis abandonnent cette solution lorsque l’environnement n’en exige plus le prix.","groupe_actuel":"BELZÉBUTH — La Vie sans jugement moral › Facette : Nature & Évolution","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belzebuth_la_vie_sans_jugement_moral_facette_nature_evolution_evolution_dirigee', 'Évolution dirigée', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":"1 PA · scène","texte_court":"jusqu''à deux adaptations, sur toi ou une cible consentante. Ni PA, ni Attribut ; elles remplacent les précédentes.","texte_reference":"Pour 1 PA, donnez à vous-même ou à une cible consentante jusqu’à deux adaptations simples du registre d’Adaptation pour la scène. Elles n’accordent ni PA ni hausse arbitraire d’Attribut et remplacent les adaptations équivalentes précédentes.","lore":"L’Élu traite l’adaptation comme un chemin qu’il peut choisir plutôt que subir. Plusieurs mutations se coordonnent, et une chair consentante peut être conduite vers la combinaison fonctionnelle que l’environnement réclame.","groupe_actuel":"BELZÉBUTH — La Vie sans jugement moral › Facette : Nature & Évolution","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belzebuth_la_vie_sans_jugement_moral_facette_nature_evolution_forme_superieure', 'Forme supérieure', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA","activation":"2 PA · scène · 2 propriétés","texte_court":"pour la scène, deux propriétés de ton répertoire, fixé avant l''achat parmi : vol soutenu (Déplacement normal), Armure corporelle 3, arme naturelle DGT 7, corps amphibie des profondeurs. Pas de cumul d''Armures corporelles.","texte_reference":"Pour 2 PA, adoptez pour la scène jusqu’à deux propriétés de votre répertoire défini avant l’achat : vol soutenu, Armure corporelle 3, arme naturelle DGT 7 ou corps amphibie des profondeurs. Aucun PA supplémentaire ni cumul d’Armures corporelles n’est accordé.\n\nRépertoire disponible : vol soutenu au Déplacement normal, Armure corporelle 3, arme naturelle DGT 7, corps amphibie des profondeurs. Le répertoire sauvegardé ne signifie pas que ces propriétés sont toutes activées ; deux au maximum sont adoptées pour une scène. On conserve la meilleure Armure corporelle, sans sommer deux sources corporelles.","lore":"Le corps ne corrige plus un détail : il adopte une configuration entière construite pour une situation. La transformation reste cohérente avec le vivant, mais révèle combien de formes Belzébuth considère comme de simples réponses possibles au même problème.","groupe_actuel":"BELZÉBUTH — La Vie sans jugement moral › Facette : Nature & Évolution","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_belzebuth_la_vie_sans_jugement_moral_maladie', 'Maladie', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"le mal qui se transmet.","profil":null,"changements":"aucun. Miasme et Affliction ne sont pas des doublons : l''Affliction est gratuite (Fonction), le Miasme coûte 1 PTV (Divinité)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belzebuth_la_vie_sans_jugement_moral_facette_maladie_miasme', 'Miasme', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 20 m","activation":"1 PA · 20 m","texte_court":"Jet contre Défense occulte : −3 à une famille d''actions jusqu''à la fin du prochain round de la cible.","texte_reference":"Pour 1 PA, imposez à une cible perçue à 20 m un Miasme après un Jet divin contre sa Défense occulte : −3 à une famille d’actions jusqu’à la fin de son prochain round. Contrairement à l’Affliction du Châtiment, le pouvoir ne demande pas le contact et reste utilisable en SR.","lore":"Le Héraut dérègle juste assez le vivant pour que fièvre, nausée ou vertige sabotent une catégorie de gestes. Rien n’est abstrait : la faiblesse vient d’un corps forcé à consacrer soudain ses ressources à un désordre imposé.","groupe_actuel":"BELZÉBUTH — La Vie sans jugement moral › Facette : Maladie","statut_regle":"correction","changements":"aucun. Miasme et Affliction ne sont pas des doublons : l''Affliction est gratuite (Fonction), le Miasme coûte 1 PTV (Divinité)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belzebuth_la_vie_sans_jugement_moral_facette_maladie_contagion', 'Contagion', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":"Après Miasme / Affliction · profil défini","texte_court":"un Miasme réussi, ou ton Affliction de Châtiment, devient une maladie transmissible dont le profil (transmission, incubation, résistance, fin) est fixé avec le MJ avant l''usage. Ni contamination de foule, ni malus qui s''empile.","texte_reference":"Vous pouvez transformer un Miasme réussi — ou votre Affliction de Châtiment — en maladie transmissible dont le profil est fixé avec le MJ avant usage. Transmission, incubation, résistance et fin de l’affection doivent être définies ; ce n’est ni une contamination automatique de foule ni un malus qui s’empile.\n\nUn Miasme doit avoir réellement réussi ; un Châtiment peut aussi employer son Affliction de Fonction, y compris lorsque cette Fonction a été apprise secondairement. La pathologie ne s’invente pas après les résistances.","lore":"La maladie créée par Belzébuth acquiert ce qui lui manquait encore : une histoire propre. Elle passe désormais d’un organisme à l’autre selon les voies que sa nature lui permet, comme toute forme de vie décidée à durer au-delà de son premier hôte.","groupe_actuel":"BELZÉBUTH — La Vie sans jugement moral › Facette : Maladie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'belzebuth_la_vie_sans_jugement_moral_facette_maladie_pestilence', 'Pestilence', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 3 PA, 1/scène","activation":"3 PA · 1/scène · rayon 10 m à 30 m","texte_court":"zone de 10 m à 30 m. Chaque cible qui échoue sa Défense occulte subit une pathologie définie avant l''usage, avec −3 aux actions physiques pour la scène. Pas de décès automatique.","texte_reference":"Pour 3 PA, une fois par scène, frappez une zone de 10 m de rayon à 30 m : chaque cible qui échoue à sa Défense occulte subit une pathologie surnaturelle définie, avec −3 aux actions physiques pour la scène. Sa durée ultérieure, sa transmission et ses soins sont fixés avant usage, sans décès automatique ni aggravation par empilement.","lore":"La pathologie déborde de l’individu et devient phénomène collectif. Une foule ou une zone commence à partager les mêmes signes, rappel brutal que Belzébuth ne sépare pas la multiplication de la vie de celle des maladies.","groupe_actuel":"BELZÉBUTH — La Vie sans jugement moral › Facette : Maladie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_abigor_le_ciel_qui_frappe_d_en_haut', 'ABIGOR — Le Ciel qui frappe d''en haut', NULL, '{"nature":"daemon","chemin":["ABIGOR — Le Ciel qui frappe d''en haut"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_abigor_le_ciel_qui_frappe_d_en_haut_vent_ciel', 'Vent & Ciel', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"du souffle au vol.","profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'abigor_le_ciel_qui_frappe_d_en_haut_facette_vent_ciel_main_du_vent', 'Main du Vent', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":null,"texte_court":"pousser, attirer ou amortir. En attaque directe : DGT 6, projection possible.","texte_reference":"Pousser, attirer ou amortir. Une attaque directe utilise DGT 6 et peut provoquer une projection.","lore":"Abigor transforme l’air en acteur de la scène. Un courant se resserre, change de sens ou devient brusquement assez dense pour pousser un corps, amortir une chute ou projeter une cible comme si le ciel lui-même avait donné un coup d’épaule.","groupe_actuel":"ABIGOR — Le Ciel qui frappe d’en haut › Facette : Vent & Ciel","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'abigor_le_ciel_qui_frappe_d_en_haut_facette_vent_ciel_pas_du_ciel', 'Pas du Ciel', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"mobilité ailée. Un Déplacement peut devenir un grand bond aérien porté par les courants ; tu finis sur un support. Pas de vol stationnaire.","texte_reference":"Mobilité ailée : un Déplacement peut devenir un grand déplacement aérien soutenu par les courants, franchir un vide ou gagner/perdre fortement de l’altitude ; le Daemon doit terminer sur un support ou s’y agripper. Pas de vol stationnaire ni de position aérienne permanente.","lore":"Le Héraut cesse de penser le mouvement uniquement depuis le sol. Les courants portent ses bonds, ses franchissements et ses changements d’altitude ; ce n’est pas un vol stationnaire, mais une manière de traiter l’espace vertical comme une route ouverte par le Ciel.","groupe_actuel":"ABIGOR — Le Ciel qui frappe d’en haut › Facette : Vent & Ciel","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'abigor_le_ciel_qui_frappe_d_en_haut_facette_vent_ciel_seigneur_des_courants', 'Seigneur des Courants', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Déplacement aérien · PA normaux","texte_court":"vol soutenu ou stationnaire jusqu''à deux fois ton Déplacement, en portant une personne si ta charge le permet. Tu peux rester en l''air entre deux rounds.","texte_reference":"Vos déplacements aériens permettent désormais un vol soutenu ou stationnaire, jusqu’à deux fois votre Déplacement normal, en portant éventuellement une personne si votre charge le permet. Vous dépensez normalement vos PA pour vous déplacer, sans en gagner pour attaquer ou agir ; cette exception autorise à rester en l’air entre deux rounds.","lore":"Les courants deviennent des appuis invisibles que l’Élu lit et chevauche avec une précision instinctive. Une rafale peut porter, infléchir une trajectoire ou arracher un compagnon au vide avant de le rendre à un support sûr.","groupe_actuel":"ABIGOR — Le Ciel qui frappe d’en haut › Facette : Vent & Ciel","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_abigor_le_ciel_qui_frappe_d_en_haut_orage', 'Orage', NULL, '{"nature":"daemon","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":"la foudre qui frappe d''en haut.","profil":null,"changements":"aucun. Distincte du Sang Orageux du Vampire : à distance, venue du ciel, contre un contact qui désorganise."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'abigor_le_ciel_qui_frappe_d_en_haut_facette_orage_foudre', 'Foudre', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":null,"texte_court":"attaque, Défense physique, DGT 7 ; peut perturber une électronique.","texte_reference":"Attaque physique DGT 7 ; peut perturber une électronique appropriée.","lore":"L’Élu appelle la décharge là où ciel et terre semblent soudain reliés par un seul trait blanc. L’orage ne distingue guère chair et circuit : tout ce qui conduit porte un instant la signature d’Abigor.","groupe_actuel":"ABIGOR — Le Ciel qui frappe d’en haut › Facette : Orage","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'abigor_le_ciel_qui_frappe_d_en_haut_facette_orage_arc_celeste', 'Arc céleste', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1/round","activation":"Après un éclair réussi · 1/round","texte_court":"après une Foudre réussie, elle frappe jusqu''à deux autres cibles à 3 m de la première, DGT 5, sur le même jet. Pas de rebond de rebond.","texte_reference":"Une fois par round, après un éclair réussi, frappez jusqu’à deux autres cibles distinctes à 3 m maximum de la première, avec DGT 5. Chacune oppose sa Défense au même jet ; ces rebonds ne produisent aucun rebond supplémentaire.","lore":"L’éclair d’Abigor ne s’éteint pas toujours avec son premier impact. Il peut bondir d’un corps à l’autre comme une nervure lumineuse qui cherche encore où décharger la colère accumulée du ciel.","groupe_actuel":"ABIGOR — Le Ciel qui frappe d’en haut › Facette : Orage","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'abigor_le_ciel_qui_frappe_d_en_haut_facette_orage_foudre_de_chatiment', 'Foudre de châtiment', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":"2 PA · 1/scène","texte_court":"DGT 12, ignore 3 Protection contre l''électricité. Tonnerre massif : jamais discret.","texte_reference":"Pour 2 PA, une fois par scène, lancez une Foudre de châtiment à DGT 12 qui ignore jusqu’à 3 points de Protection réellement applicable à l’électricité. Le tonnerre reste massif et l’attaque ne peut pas être discrète.","lore":"Ici, le tonnerre cesse d’être un avertissement. La foudre tombe avec une violence de sentence céleste, traverse volontiers le métal et laisse derrière elle l’odeur d’ozone d’un orage qu’aucun témoin ne peut prétendre ne pas avoir entendu.","groupe_actuel":"ABIGOR — Le Ciel qui frappe d’en haut › Facette : Orage","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_abigor_le_ciel_qui_frappe_d_en_haut_tempete', 'Tempête', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"le vent comme terrain.","profil":null,"changements":"Vent mauvais complété (ni PA, ni rayon, ni durée) : 1 PA selon les précisions communes, 5 m et durée de scène alignés sur la Brume de Vephar, déplacement au double comme Déluge. **Proposition** : à confirmer d''un mot. Coquille de Typhon corrigée. Écart de source : Typhon 3 PA sur le site, 4 PA dans le livre V6."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'abigor_le_ciel_qui_frappe_d_en_haut_facette_tempete_vent_mauvais', 'Vent mauvais', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"une zone de vent violent de 5 m de rayon, à portée de vue, pour la scène : −3 aux tirs qui la traversent, déplacements au double.","texte_reference":"Créer une zone de vent violent : −3 aux tirs traversant la zone et déplacements difficiles.","lore":"Un courant hostile s’installe dans la zone, irrégulier, brutal, toujours placé au pire endroit. Les trajectoires se dérobent et chaque pas donne l’impression d’avancer contre un ciel qui a décidé de repousser les intrus.","groupe_actuel":"ABIGOR — Le Ciel qui frappe d’en haut › Facette : Tempête","statut_regle":"correction","changements":"Vent mauvais complété (ni PA, ni rayon, ni durée) : 1 PA selon les précisions communes, 5 m et durée de scène alignés sur la Brume de Vephar, déplacement au double comme Déluge. **Proposition** : à confirmer d''un mot. Coquille de Typhon corrigée. Écart de source : Typhon 3 PA sur le site, 4 PA dans le livre V6."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'abigor_le_ciel_qui_frappe_d_en_haut_facette_tempete_il_de_la_tempete', 'Œil de la tempête', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":"1 PA · rayon 3 m · scène","texte_court":"un calme de 3 m autour de toi dans une tempête, pour la scène. Contre une tempête surnaturelle étrangère, Jet de pouvoir contre sa Puissance d''abord. N''arrête pas une attaque venue d''ailleurs.","texte_reference":"Vous ménagez dans une tempête un espace calme de 3 m de rayon autour de vous, protégeant ceux qui s’y trouvent de ses vents et projections ordinaires pour la scène. Une tempête surnaturelle étrangère exige d’abord un Jet divin contre sa Puissance ; l’abri n’arrête pas les attaques qui n’en proviennent pas.\n\nActivation : 1 PA selon le coût commun des actions non gratuites. L’espace calme ne protège ni d’une balle tirée de l’extérieur ni d’un pouvoir sans rapport avec la tempête.","lore":"Au milieu du tumulte, l’Élu impose un calme presque irréel. La tempête continue de rugir tout autour, mais un îlot choisi demeure respirable, comme si Abigor avait laissé un centre immobile à sa propre colère.","groupe_actuel":"ABIGOR — Le Ciel qui frappe d’en haut › Facette : Tempête","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'abigor_le_ciel_qui_frappe_d_en_haut_facette_tempete_typhon', 'Typhon', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 3 PA, 1/scène","activation":"3 PA · 1/scène · rayon 10 m à 30 m","texte_court":"zone de 10 m à 30 m. Chaque cible se défend contre le même jet : DGT 12, recul jusqu''à 3 m, terrain bouleversé.","texte_reference":"Pour 3 PA, une fois par scène, et frappe une zone de 10 m de rayon à 30 m : DGT 12, recul jusqu’à 3 m et terrain bouleversé selon les obstacles réels. Chaque cible se défend contre le même jet ; aucun dégât répété ni typhon régional n’est créé.","lore":"Le Héraut ouvre assez grand la colère du ciel pour que le paysage lui-même commence à céder. Vents, débris et pression composent une masse mouvante dont l’échelle rappelle pourquoi les anciennes tempêtes portaient des noms divins.","groupe_actuel":"ABIGOR — Le Ciel qui frappe d’en haut › Facette : Tempête","statut_regle":"correction","changements":"Vent mauvais complété (ni PA, ni rayon, ni durée) : 1 PA selon les précisions communes, 5 m et durée de scène alignés sur la Brume de Vephar, déplacement au double comme Déluge. **Proposition** : à confirmer d''un mot. Coquille de Typhon corrigée. Écart de source : Typhon 3 PA sur le site, 4 PA dans le livre V6."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_baal_la_guerre_elle_meme', 'BAAL — La Guerre elle-même', NULL, '{"nature":"daemon","chemin":["BAAL — La Guerre elle-même"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_baal_la_guerre_elle_meme_armes', 'Armes', NULL, '{"nature":"daemon","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":"l''arme devient divine.","profil":null,"changements":"aucun ; une propriété identique venue d''Arme exaltée ne s''ajoute pas."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'baal_la_guerre_elle_meme_facette_armes_arme_consacree', 'Arme consacrée', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, 1 PA","activation":null,"texte_court":"une arme tenue devient divine pour la scène, +1 DGT.","texte_reference":"Une arme tenue devient divine pour la scène et gagne +1 DGT.","lore":"Pour Baal, l’arme importe parce qu’elle est déjà entre les mains de quelqu’un prêt à s’en servir. La consécration ne remplace ni technique ni courage : elle fait simplement de l’objet choisi une véritable extension de la Guerre pour la durée de l’affrontement.","groupe_actuel":"BAAL — La Guerre elle-même › Facette : Armes","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'baal_la_guerre_elle_meme_facette_armes_arme_de_guerre', 'Arme de guerre', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R — prérequis Arme consacrée","activation":null,"texte_court":"+2 DGT et une propriété : Perforante (ignore 3 Armure), Terrassante ou Entravante.","texte_reference":"Le bonus passe à +2 DGT et l’arme reçoit une propriété : Perforante (ignore 3 Armure), Terrassante ou Entravante.","lore":"La consécration atteint un degré où l’arme reçoit une intention tactique. Percer une ligne, terrasser une masse ou entraver un adversaire devient une propriété de la manifestation divine elle-même, comme si Baal avait choisi le rôle que cet outil doit jouer dans la bataille.","groupe_actuel":"BAAL — La Guerre elle-même › Facette : Armes","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'baal_la_guerre_elle_meme_facette_armes_instrument_de_victoire', 'Instrument de victoire', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R — prérequis Arme de guerre","activation":null,"texte_court":"deux propriétés à la fois.","texte_reference":"L’arme consacrée peut porter deux propriétés simultanément.","lore":"L’arme consacrée cesse d’avoir une seule vocation. Entre les mains du Héraut de Baal, elle porte plusieurs réponses de guerre à la fois, comme un outil forgé non pour un duel particulier mais pour la victoire elle-même.","groupe_actuel":"BAAL — La Guerre elle-même › Facette : Armes","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_baal_la_guerre_elle_meme_force_violence', 'Force & Violence', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"la force brute.","profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'baal_la_guerre_elle_meme_facette_force_violence_puissance_guerriere', 'Puissance guerrière', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"+3 aux tests de force brute, de renversement et d''immobilisation.","texte_reference":"+3 aux tests de force brute et aux tentatives de renversement ou immobilisation.","lore":"Baal exalte la force utile à la lutte : saisir, rompre, renverser, maintenir. Le corps du Héraut paraît connaître spontanément les angles où la puissance devient domination physique plutôt que simple démonstration musculaire.","groupe_actuel":"BAAL — La Guerre elle-même › Facette : Force & Violence","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'baal_la_guerre_elle_meme_facette_force_violence_impact_de_guerre', 'Impact de guerre', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"une attaque physique à DR 2+ peut choisir +3 DGT, ou une projection ou un renversement majeur.","texte_reference":"Les attaques physiques du Daemon avec DR 2+ peuvent choisir +3 DGT ou une projection/renversement majeur.","lore":"Un coup bien placé reçoit le poids d’une charge militaire. Il peut chercher la destruction pure ou convertir la violence en déplacement brutal, arrachant l’adversaire à son appui comme si toute une mêlée avait poussé derrière le geste.","groupe_actuel":"BAAL — La Guerre elle-même › Facette : Force & Violence","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'baal_la_guerre_elle_meme_facette_force_violence_carnage', 'Carnage', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1/scène","activation":null,"texte_court":"quand tu mets un adversaire hors combat, attaque gratuite immédiate contre une autre cible à portée. Pas de chaîne.","texte_reference":"Lorsqu’il met un adversaire hors combat avec une attaque, effectuer immédiatement une attaque gratuite contre une autre cible à portée. Une seule activation dans le round : aucune chaîne infinie.","lore":"La chute d’un adversaire ouvre immédiatement la suivante. Le combattant ne s’arrête pas pour constater sa victoire : il transforme l’élan, le sang et la brèche créée en une nouvelle attaque avant que la ligne ennemie ne se referme.","groupe_actuel":"BAAL — La Guerre elle-même › Facette : Force & Violence","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_baal_la_guerre_elle_meme_strategie_victoire', 'Stratégie & Victoire', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"lire la bataille, la diriger.","profil":null,"changements":"aucun (Maître de bataille est fort, mais c''est un palier III à 1/scène)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'baal_la_guerre_elle_meme_facette_strategie_victoire_lecture_du_champ_de_bataille', 'Lecture du champ de bataille', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":"1 PA · bonus 1/scène","texte_court":"tu identifies la faiblesse tactique exploitable ou l''appui dont dépend le rapport de force. 1/scène, la première action qui exploite ce diagnostic (la tienne ou celle d''un allié) gagne +3.","texte_reference":"Après 1 PA d’observation, identifiez la faiblesse tactique actuellement exploitable ou l’appui dont dépend le rapport de force. Une fois par scène, la première action de vous-même ou d’un allié qui exploite ce diagnostic gagne +3, sans révéler un ennemi entièrement imperceptible.","lore":"Le combat se simplifie dans l’esprit du stratège en lignes, menaces et ouvertures. Là où d’autres voient du chaos, le Héraut distingue l’élément qui fera basculer les secondes suivantes : un flanc vide, une arme clé, une position trop exposée.","groupe_actuel":"BAAL — La Guerre elle-même › Facette : Stratégie & Victoire","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'baal_la_guerre_elle_meme_facette_strategie_victoire_ordre_de_guerre', 'Ordre de guerre', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":null,"texte_court":"un allié gagne +3 à sa prochaine action de combat conforme à l''ordre, avant la fin du prochain round.","texte_reference":"Donner à un allié +3 sur sa prochaine action de combat cohérente avec l’ordre avant la fin du prochain round.","lore":"La voix de Baal ne commande pas par prestige mais par justesse tactique. Une instruction précise donne à l’allié un objectif immédiatement lisible et transforme son prochain geste en pièce consciente d’un plan plus vaste.","groupe_actuel":"BAAL — La Guerre elle-même › Facette : Stratégie & Victoire","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'baal_la_guerre_elle_meme_facette_strategie_victoire_maitre_de_bataille', 'Maître de bataille', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":null,"texte_court":"jusqu''à trois alliés gagnent chacun 1 PA de réaction, seulement pour Déplacement, Défense active ou Assistance, avant le début du prochain round.","texte_reference":"Jusqu’à trois alliés reçoivent chacun 1 PA de réaction supplémentaire utilisable uniquement pour Déplacement, Défense active ou Assistance de combat avant le début du prochain round.","lore":"Un ordre bref suffit à redistribuer le rythme d’une escarmouche. Les alliés préparés par le Héraut voient venir l’instant critique et disposent encore d’un mouvement, d’une parade ou d’un appui quand l’ennemi les croyait déjà engagés ailleurs.","groupe_actuel":"BAAL — La Guerre elle-même › Facette : Stratégie & Victoire","statut_regle":"correction","changements":"aucun (Maître de bataille est fort, mais c''est un palier III à 1/scène)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'daemon', 'daemon_morrighan_la_corneille_etrangere', 'MORRIGHAN — La Corneille étrangère', NULL, '{"nature":"daemon","chemin":["MORRIGHAN — La Corneille étrangère"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_morrighan_la_corneille_etrangere_guerre_frenesie', 'Guerre & Frénésie', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"la Corneille se nourrit des tombés.","profil":null,"changements":"aucun sur Fureur de la Corneille (Frénésie confirmée par l''auteur le 30/10). *Retiré le 30/10* : la version « état propre au Daemon » que j''avais écrite. La Frénésie est une règle du moteur de Vérité que le texte d''origine emploie volontairement ; la réécrire était une erreur."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'morrighan_la_corneille_etrangere_facette_guerre_frenesie_fureur_de_la_corneille', 'Fureur de la Corneille', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":"Frénésie volontaire · R","texte_court":"tu entres volontairement en Frénésie ; +1 aux tests physiques, avec les règles normales d''Impulsion.","texte_reference":"En Frénésie volontaire, votre bonus aux tests physiques passe de +1 à +3. Les règles d’Impulsion et la perte de contrôle restent applicables, sans PA supplémentaire ni cumul avec un autre bonus équivalent de Frénésie.\n\nLe +3 est un bonus conditionnel aux tests physiques en Frénésie, pas une hausse des Attributs ou des PV maximum.","lore":"La Morrighan ne traite pas la Frénésie comme une perte honteuse de contrôle. Le Daemon peut ouvrir volontairement la porte à la fureur guerrière et laisser son corps suivre quelques instants le rythme brutal des anciens champs de bataille.","groupe_actuel":"MORRIGHAN — La Corneille étrangère › Facette : Guerre & Frénésie","statut_regle":"correction","changements":"aucun sur Fureur de la Corneille (Frénésie confirmée par l''auteur le 30/10). *Retiré le 30/10* : la version « état propre au Daemon » que j''avais écrite. La Frénésie est une règle du moteur de Vérité que le texte d''origine emploie volontairement ; la réécrire était une erreur."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'morrighan_la_corneille_etrangere_facette_guerre_frenesie_sang_du_champ_de_bataille', 'Sang du champ de bataille', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1/round","activation":"Après mise hors combat · 1/round","texte_court":"quand un véritable adversaire tombe hors combat à 10 m, ta prochaine attaque physique réussie avant la fin du round suivant gagne +2 DGT.","texte_reference":"Une fois par round, lorsqu’un véritable adversaire tombe hors combat à 10 m, votre prochaine attaque physique réussie avant la fin du round suivant gagne +2 DGT. Ce bénéfice est distinct du bonus de test de Frénésie et ne s’empile pas avec lui-même.","lore":"La chute d’un ennemi change immédiatement la température de la bataille pour un Héraut de la Corneille. Cet instant où une ligne cède, où le sang touche le sol et où les autres comprennent qu’ils peuvent tomber devient l’élan de sa prochaine action.","groupe_actuel":"MORRIGHAN — La Corneille étrangère › Facette : Guerre & Frénésie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'morrighan_la_corneille_etrangere_facette_guerre_frenesie_morrigu', 'Morrígu', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":"2 PA · 1/scène · 3 alliés à 10 m","texte_court":"jusqu''à trois alliés à 10 m gagnent +2 DGT au corps à corps et ignorent les effets de Tendu et Paniqué dus à la seule peur, pour la scène. Aucune fureur imposée.","texte_reference":"Pour 2 PA, une fois par scène, jusqu’à trois alliés à 10 m gagnent +2 DGT au corps à corps et ignorent les conséquences de Tendu et Paniqué causées uniquement par la peur pour la scène. Les minima dus aux blessures restent applicables et aucune Frénésie n’est imposée.","lore":"Le cri de guerre de la Morrighan réveille une férocité de champ de bataille chez ceux qu’elle reconnaît. La peur tactique s’efface derrière l’élan de mêlée, et chaque combattant semble frapper avec la certitude d’appartenir à une charge plus ancienne que lui.","groupe_actuel":"MORRIGHAN — La Corneille étrangère › Facette : Guerre & Frénésie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_morrighan_la_corneille_etrangere_mort_presages', 'Mort & Présages', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"voir la mort, l''annoncer.","profil":null,"changements":"Mauvais présage renommé Présage funeste (homonyme de la Faveur d''Ibn al-Berih, même Divinité, effet différent)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'morrighan_la_corneille_etrangere_facette_mort_presages_corneille_du_trepas', 'Corneille du trépas', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"tu vois aussitôt les mourants, les morts récentes et les lieux marqués par une mort violente.","texte_reference":"Voir immédiatement les mourants, les morts récentes et les lieux fortement marqués par une mort violente.","lore":"La mort laisse des traces que la Morrighan connaît depuis les premiers champs de bataille. Le Héraut reconnaît les corps qui approchent du dernier souffle, les morts encore fraîches et les lieux où la violence a suffisamment frappé pour marquer l’air.","groupe_actuel":"MORRIGHAN — La Corneille étrangère › Facette : Mort & Présages","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'morrighan_la_corneille_etrangere_facette_mort_presages_mauvais_presage', 'Présage funeste', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, Réaction, 1/scène","activation":null,"texte_court":"après qu''une cible visible réussit une action dangereuse, impose-lui −3 après coup, si cela suffit à changer la réussite en échec simple. Jamais contre une réussite largement supérieure.","texte_reference":"Après qu’une cible visible réussit une action dangereuse, lui imposer −3 rétroactivement si cela suffit à transformer la réussite en échec simple. Ne peut jamais renverser une réussite largement supérieure.","lore":"Une réussite trop fragile peut soudain porter l’ombre d’un corbeau. Le geste qui semblait juste rencontre le détail malheureux déjà possible — appui qui glisse, regard qui hésite, mécanisme qui accroche — et l’issue heureuse se décompose au dernier instant.","groupe_actuel":"MORRIGHAN — La Corneille étrangère › Facette : Mort & Présages","statut_regle":"correction","changements":"Mauvais présage renommé Présage funeste. Mauvais présage renommé Présage funeste (homonyme de la Faveur d''Ibn al-Berih, même Divinité, effet différent)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'morrighan_la_corneille_etrangere_facette_mort_presages_annonce_de_la_chute', 'Annonce de la chute', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1/scène","activation":"Observer 1 round · 1/scène","texte_court":"après un round à observer une cible, le MJ indique une faiblesse réelle et exploitable. Jusqu''à la fin de la scène, tes attaques qui l''exploitent ignorent 3 Protection pertinente.","texte_reference":"Une fois par scène, après avoir observé une cible pendant un round, le MJ indique une faiblesse réelle et actuellement exploitable. Jusqu’à la fin de la scène, vos attaques qui l’exploitent ignorent 3 points de Protection pertinente, sans créer une vulnérabilité ou contourner une invulnérabilité fondamentale.","lore":"Après avoir longuement regardé une cible, le Héraut distingue le présage qui pourrait annoncer sa perte. Ce n’est pas une prophétie garantie : plutôt la faiblesse présente que la Corneille choisirait si elle devait déjà tourner au-dessus du futur cadavre.","groupe_actuel":"MORRIGHAN — La Corneille étrangère › Facette : Mort & Présages","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'daemon', 'daemon_morrighan_la_corneille_etrangere_royaute_magie', 'Royauté & Magie', NULL, '{"nature":"daemon","forme":"une_porte","forme_lot":"une porte","verrou":"ordre_paliers","portes":null,"identite":"le statut et les rites de la Corneille.","profil":null,"changements":"référence morte aux « Techniques Mage » retirée ; phrase Builder retirée. Ressort propre déjà là : le rituel de dix minutes, limité au domaine de la Corneille."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'morrighan_la_corneille_etrangere_facette_royaute_magie_autorite_ancienne', 'Autorité ancienne', NULL, '{"nature":"daemon","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"+3 avec les esprits, les Keltas et les serviteurs divins quand tu invoques ton statut auprès de Morrighan.","texte_reference":"+3 dans les interactions avec esprits, Keltas et serviteurs divins lorsqu’il invoque explicitement son statut auprès de Morrighan.","lore":"Le Héraut parle aux esprits en portant ouvertement le nom et le rang que lui reconnaît la Morrighan. Les créatures qui connaissent encore les vieilles hiérarchies ne sont pas forcées d’obéir, mais elles savent exactement quelle Cour vient de leur adresser la parole.","groupe_actuel":"MORRIGHAN — La Corneille étrangère › Facette : Royauté & Magie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'morrighan_la_corneille_etrangere_facette_royaute_magie_sorcellerie_des_corneilles', 'Sorcellerie des Corneilles', NULL, '{"nature":"daemon","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":"Rituel · 10 minutes · difficulté 15","texte_court":"un domaine rituel étroit de Morrighan (sang, présage, morts, corvidés, bataille), aux usages Initiale / Mineure fixés avec le MJ avant l''achat. Chaque rituel prend dix minutes : Difficulté de base 15, portées et oppositions du moteur magique. Aucune Affinité de Mage, aucune Tension.","texte_reference":"Choisissez un domaine rituel étroit lié à Morrighan et définissez ses usages Initials / Mineurs avec le MJ avant l’achat. Chaque rituel demande dix minutes et suit une Difficulté de base 15, les portées et oppositions du moteur magique, sans ouvrir d’autre Affinité ni les Techniques Mage.\n\nLes PA tactiques, portée et opposition d’un effet restent ceux du moteur magique adapté à son usage Initial / Mineur. Le rituel ne donne ni Affinité de Mage ni technique personnelle ; le répertoire saisi ne constitue pas une validation MJ.","lore":"La magie de la Morrighan se pratique avec les matières qui lui appartiennent : sang versé, présages, morts, corvidés et mémoire des batailles. Le Héraut apprend à assembler ces signes en petits rites précis plutôt qu’à prétendre maîtriser toute sorcellerie.","groupe_actuel":"MORRIGHAN — La Corneille étrangère › Facette : Royauté & Magie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'morrighan_la_corneille_etrangere_facette_royaute_magie_couronne_noire', 'Couronne noire', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène","activation":"1 PA · 1/scène · 3 esprits","texte_court":"ton autorité divine contre la Défense occulte de jusqu''à trois esprits mineurs de Mort ou de Guerre qui reconnaissent Morrighan. Pour la scène, un passage, une trêve ou un témoignage qu''ils peuvent fournir. Ni serviteur, ni lien permanent.","texte_reference":"Une fois par scène, pour 1 PA, opposez votre autorité divine à la Défense occulte de jusqu’à trois esprits mineurs de Mort ou de Guerre qui reconnaissent Morrighan. En réussite, vous obtenez pour la scène un passage, une trêve ou un témoignage qu’ils peuvent réellement fournir, sans serviteur combattant ni connaissance créée.\n\nLes esprits doivent réellement reconnaître Morrighan et disposer du passage ou de l’information demandée. Aucun lien de servitude permanent n’est créé.","lore":"La souveraineté de la Corneille devient presque visible autour de l’Élu. Ceux qui savent ce que représente un Héraut de la Morrighan mesurent leurs mots et leurs gestes comme devant une autorité ancienne qui n’a jamais eu besoin d’un trône terrestre.","groupe_actuel":"MORRIGHAN — La Corneille étrangère › Facette : Royauté & Magie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'daemon', 'daemon_clean_fonctions_daemoniaques_formation_secondaire_formation_secondaire', 'Formation secondaire', NULL, '{"nature":"daemon","cout":3,"cout_actuel":3,"palier":null,"porte":null,"hors_voie":true,"acces":"Option avancée","activation":"Apprentissage · Fonction secondaire","texte_court":"Après mentor et accord narratif, choisissez une deuxième Fonction différente : vous recevez son Empreinte et pouvez acheter ses talents, sans obtenir une seconde Divinité ni Faveur. Le Builder doit mémoriser ce choix et appliquer ses véritables accès ; une case cochée par le joueur n’est pas une autorisation MJ.","texte_reference":"Après mentor et accord narratif, choisissez une deuxième Fonction différente : vous recevez son Empreinte et pouvez acheter ses talents, sans obtenir une seconde Divinité ni Faveur. Le Builder doit mémoriser ce choix et appliquer ses véritables accès ; une case cochée par le joueur n’est pas une autorisation MJ.\n\nIl faut un mentor, du temps narratif et une justification dans la Cour. La Fonction principale, les bonus de Divinité et la Maisonnée restent uniques ; le choix ou un texte du joueur ne vaut pas autorisation MJ.","lore":"Certaines Cours refusent de réduire un Héraut à son premier office. Après avoir servi, observé et appris auprès d’un véritable mentor, l’Élu peut être reconnu dans une seconde Fonction — avec les devoirs, les réflexes et la culture que ce rôle implique.","groupe_actuel":"Fonctions daemoniaques › Formation secondaire","statut_regle":"origine","changements":"Laissé hors des voies par le lot (moteur, maîtrise ou rang)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
